window.REPORTS=[{"date": "2026-10-29", "edition": "5条 · 产品产业3条／研究2条", "updated": "10:45", "intro": "宇树第三季度营收同比增长69.93%，但归母净利润同比下降17.37%，研发投入同时明显增加，说明业务扩张与研发投入、利润压力并存；本条核验的财务指标未给出交付台数，不能据此推算机器人出货。新品与工具链继续向具体工作流延伸：Sagi尝试把移动、操作和人工协助结合，Tsing-Ego PRO瞄准工业数据采集，Genie Sim则补充柔性物体仿真与评测，但三者目前都缺少独立、连续运行证据。", "items": [{"title": "国内产业｜宇树单季营收增长，利润同比下降", "date": "2026-10-28晚披露，10月29日公告", "body": "宇树科技未经审计的三季报显示，2026年第三季度营业收入6.65亿元，同比增长69.93%；归母净利润1.13亿元，同比下降17.37%。同期研发投入同比增长249.58%。收入扩张、利润回落与研发加码同时出现，是本期财报最明确的变化。", "analysis": "研发增长可能影响短期利润，但仅凭财务数据无法拆分具体原因，也不能判断机器人自主作业成熟度。收入包含的产品及业务结构、交付台数均未在本条证据中披露，因此不从营收反推整机销量。", "sources": [{"label": "巨潮资讯：宇树科技三季度报告", "url": "https://static.cninfo.com.cn/finalpage/2026-10-29/1225637442.PDF"}, {"label": "上海证券报财报报道", "url": "https://paper.cnstock.com/html/2026-10/29/content_2282956.htm"}]}, {"title": "国内新品｜PHYMI发布四轮腿行动伙伴Sagi", "date": "2026-10-28", "body": "PHYMI发布首款Physical Agent行动伙伴Sagi，以四轮腿、拟人上身和小货箱组合移动与操作能力。发布影片展示搬运露营装备、准备办公室文件和会议物品、协作处理社区快递等场景。创始人刘念秋称，LINK机制会在系统需要信息或判断时引入人类协助。", "analysis": "产品形态强调日常任务中的移动、载物与操作协同，并把人工介入设计成系统组成部分。不过现有证据主要是发布影片和创始人采访，售价、交付时间、任务成功率及人工介入比例均未核验，不能据此认定已经商用或可连续无人运行。", "sources": [{"label": "凤凰财经：新品发布报道", "url": "https://finance.ifeng.com/c/8xaTaH7MHtq"}, {"label": "极客公园采访转载", "url": "https://www.aitntnews.com/newDetail.html?newId=30705"}]}, {"title": "国内工具链｜Tsing-Ego PRO发布并开启预订", "date": "2026-10-27展会发布；10月28日报道", "body": "清研精准在SAECCE 2026展示工业第一视角多视角同步采集产品Tsing-Ego PRO，并开启预订。厂商称产品支持轻量穿戴、端侧质检及抗环境干扰；官网介绍其通过多摄像头与激光对齐，采集视觉、空间和人类动作数据。配套Robot-in-the-Loop中试方案用于复刻工位机构、接口与流程，在进厂前测试后再到真实场景验收。", "analysis": "这一路线试图把数据采集和进厂前集成验证前置，有望减少现场调试的不确定性，但降低集成风险仍是分析而非已验证结果。预订不等于交付，价格、重量、续航及同步误差尚未核验，“车规级”也仅属于厂商口径。", "sources": [{"label": "具身智能之家转载清研精准发布材料", "url": "https://www.jushenhome.com/news/2159"}, {"label": "清研精准官方产品页", "url": "https://www.tsingstandard.com/products.html"}]}, {"title": "算法研究｜海外｜SuperMimic尝试降低全身动作训练成本", "date": "2026-10-20 UTC提交预印本（北京时间10月21日）；近期漏报补入", "body": "SuperMimic先从仿真数据学会预测动作后果，再利用这个世界模型指导动作策略更新。作者报告单张H100训练3小时超过已发布SONIC检查点的回报，并展示同一策略运行于宇树G1真机。作者项目页标注CoRL 2026。", "analysis": "这可能降低全身动作训练门槛，但评测使用训练动作，不能证明未见动作泛化；对照硬件和数据不同，不是同预算效率比较。训练耗时包含模型拟合与策略更新、不含评测，也不是生产任务可靠性验证。", "sources": [{"label": "作者项目与实验口径", "url": "https://supermimic.github.io/"}, {"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.28480"}]}, {"title": "算法研究｜国内｜Genie Sim增强柔性物体仿真与模型评测", "date": "2026-10-28", "body": "智元升级Genie Sim，增加柔性物体仿真、模型评测和强化学习后训练功能。据公司披露，系统在4款机器人本体、22项任务中的仿真与真机任务得分相关性为96.7%；代码计划在GitHub更新，资产和数据集也计划开放。", "analysis": "96.7%是任务得分相关性，不是成功率，也不能解释为误差仅3.3%。结果来自公司自测，尚未证明复杂接触都能准确复现；本次代码是否已可下载也未核验，因此现阶段更适合作为仿真筛选能力线索，而非工业部署证据。", "sources": [{"label": "泰伯转载界面：升级及测试口径", "url": "https://www.taibo.cn/newsflashes/31616488"}, {"label": "证券时报人民财讯报道转载", "url": "https://stock.stockstar.com/IG2026102800027734.shtml"}]}], "followups": ["跟踪Google DeepMind于10月27日发布的Genie 4：目前是面向可信测试者的研究预览，机器人训练环境只是未来应用方向，尚无真机收益证据；后续关注开放测试、动作接口及机器人验证。它与智元Genie Sim不是同一产品。来源：https://deepmind.google/blog/genie-4-a-new-generation-of-world-simulation/", "等待智元10月29日基座模型的正式材料，核对模型角色、支持本体、真机任务和人工介入口径；同时关注11月2日G2便利店24小时直播中的接管次数、失败类型及恢复方式。", "继续核验Sagi和Tsing-Ego PRO的价格、交付安排及可重复运行数据；若出现客户确认、独立评测或明确交付数量，再更新商业化阶段判断。"], "coverage": "覆盖2026-10-28 10:37至2026-10-29 10:45（UTC+8）；SuperMimic为此前漏报补入。重点公众号存在原文访问与索引滞后缺口，未完整订阅微信。"}, {"date": "2026-10-28", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:37", "intro": "H2-X官网现列出16.9万元含税起价和基础款／EDU版差异，比此前价格未披露更便于采购评估；基础款不支持二次开发，选型需核对版本。小米灵巧手与Luxonis视觉载板分别补充操作和感知硬件，但参数不能替代长期作业验证。研究方面，Genie Master与EgoForesight尝试利用执行反馈和含噪示范改进学习，证据仍限于公司验证及小规模真机实验。", "items": [{"title": "新品规格｜国内｜H2-X官网列出16.9万元起价与版本差异", "date": "10月21日发布；10月28日核验官网，页面更新时间未注明", "body": "官网显示H2-X基础款含税16.9万元，EDU版需联系销售；整机31自由度、含双电池重65公斤以上，标称静态续航约8小时、持续行走约4小时。基础款不支持二次开发，EDU版支持，并可选高算力模组及灵巧手。", "analysis": "价格公开降低了初步选型门槛，但续航、负载均为厂商口径，交付日期、带载工况和客户验收尚未核验。", "sources": [{"label": "宇树H2-X官方规格与价格", "url": "https://www.unitree.com/cn/mobile/H2-X/"}]}, {"title": "灵巧手｜国内｜小米披露21自由度工业仿生灵巧手", "date": "2026-10-27", "body": "据IT之家直接引述小米技术官微，新仿生手采用21自由度、26电机混合驱动和1500点全掌触觉，并引入腱绳张力控制、散热优化及模块化维护。团队从汽车工厂典型流程采集分析作业数据，并以真实工具和零件制作数字资产进行仿真抓握验证。", "analysis": "其工程方向贴近汽车制造，但尚无独立真机成功率、循环寿命、售价及量产交付信息，数据覆盖不能等同于完成相应工序。", "sources": [{"label": "IT之家引述小米技术", "url": "https://www.ithome.com/1/018/345.htm"}]}, {"title": "视觉硬件｜海外｜Luxonis发布五路相机视觉载板OAK 4 FFC", "date": "2026-10-27", "body": "70×53毫米的OAK 4 FFC最多连接五路摄像头，可在板端完成同步、深度、目标检测和神经网络推理，并利用自然场景特征动态校正相机相对位置。开发套件定价849美元并标注现发货；730美元裸板计划2027年第一季度推出，摄像头需另购。", "analysis": "该模块可分担机器人主计算机的视觉处理和校准工作，但不能替代全部主算力，现货状态也不等于客户已收货。", "sources": [{"label": "Luxonis官方产品与价格", "url": "https://www.luxonis.com/oak4-ffc"}, {"label": "Humanoids Daily发布报道", "url": "https://www.humanoidsdaily.com/news/luxonis-oak-4-ffc-humanoid-vision-computer"}]}, {"title": "产业整合｜海外｜FFR完成FFAI机器人业务及资产收购", "date": "2026-10-23交割；2026-10-26公告", "body": "FFR公告称，已于23日完成收购FFAI机器人业务及资产，以普通股和无投票权可转优先股支付对价，并将统一智能平台更名为FF OmniMind。公司给出被收购业务全年销售及出货约2000台指引，包含交割前期间；合并报表仅从23日起计入。", "analysis": "股权交易完成不代表产品能力已经验证，销售及出货的混合指引也不能视为付费客户实际部署数量。", "sources": [{"label": "FFR公司交割公告", "url": "https://www.prnewswire.com/news-releases/ff-eai-robotics-ecosystem-ffr-completes-acquisition-of-ffai-robotics-business-establishing-a-nasdaq-listed-humanoid-and-bionic-robotics-platform-october-robot-sales-expected-to-exceed-300-units-unveils-ff-omnimind-a-unified-a-302919898.html"}]}, {"title": "算法研究｜国内｜Genie Master让机器人从执行失败处继续改进", "date": "2026-10-27", "body": "智元发布Genie Master，以具身执行协议连接任务判断、执行和反馈，受阻后保留进度并重新规划。一层把成败经验整理为提示与长期记忆，另一层将失败、调整和结果用于动作策略训练。公司称G2已在便利店打包、取货及补货任务中验证。", "analysis": "框架强调跨任务持续改进，但无人在环和自主进化仍属公司主张，完整成功率、接管率与连续运行数据尚未披露。", "sources": [{"label": "新浪科技发布报道", "url": "https://finance.sina.com.cn/jjxw/2026-10-27/doc-iniwrzht4610342.shtml"}, {"label": "PChome框架与验证边界", "url": "https://article.pchome.net/news/16488.html"}]}, {"title": "算法研究｜海外｜EgoForesight降低含噪人类示范对机器人训练的干扰", "date": "2026-10-22预印本；近期研究补充", "body": "EgoForesight降低含噪第一视角动作标签的训练权重，并用示范实际结果塑造动作表征，部署时无需未来信息。Galaxea R1 Pro在四项双臂双手任务中各用100条遥操作示范、测试20次，平均成功率63.8%；代码已公开。", "analysis": "结果来自小规模真机实验且预训练私有数据未开放，尚不能外推到全身移动操作或通用生产任务。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.31845"}, {"label": "作者代码仓库", "url": "https://github.com/LinShan-Bin/EgoForesight"}]}], "followups": ["11月2日复查智元六台G2的24小时直播，重点记录失败次数、人工接管、每班任务量；Genie Sim及29日基座模型出现正式材料后再评估。", "等待小米披露真机循环寿命和任务成功率，并核对Luxonis多路相机独立时延、完整配置价格及实际到货情况，避免以硬件参数替代作业表现。", "FFR披露月末实际销售出货及后续财务报表、EgoForesight出现公开数据或独立复现时更新判断；公司预测不计作已部署数量。"], "coverage": "覆盖2026-10-27 10:35至2026-10-28 10:37（UTC+8）；EgoForesight为10月22日近期研究补充。重点公众号存在索引滞后与访问缺口。"}, {"date": "2026-10-27", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:35", "intro": "昨日预告中的智元G2 Max已有正式发布材料，工业选型可以进一步核对负载与作业边界；睿尔曼GEN62和Realbotix Echo也分别明确了轻载操作、社交交互的产品定位。GXO与Agility把既有合作扩展到两个新站点，意味着客户愿意继续推进，但新增部署仍是2027年计划。CO01和LogLook分别尝试用失败经验、按需视觉记忆减少重复学习与上下文开销，结果仍需区分企业真机自测和仿真。", "items": [{"title": "国内新品｜智元正式发布G2 Max，补充重载作业数据", "date": "2026-10-26", "body": "G2 Max曾在7月WAIC亮相，本次于AI WAVE正式发布，面向拆码垛、物料转运和产线供料。厂商披露单臂负载20kg、双臂额定40kg、峰值50kg，手臂重复定位精度≤±0.5mm；价格、交付规模和独立长时测试尚未公布。", "analysis": "本次正式材料为工业选型提供依据；参数仍属厂商口径，需结合客户验收、接管率和长时运行验证，“安规级”不代表本次已核验第三方认证。", "sources": [{"label": "IT之家发布报道", "url": "https://www.ithome.com/1/017/951.htm"}, {"label": "盖世具身智能", "url": "https://auto.gasgoo.com/news/202610/26I70475937C601.shtml"}]}, {"title": "海外部署｜GXO与Agility把Digit合作扩展至两个美国站点", "date": "2026-10-26", "body": "双方计划在北卡罗来纳州Statesville和田纳西州Lebanon站点新增部署，预计2027年初先采用Digit 4，待Digit 5商业可用后迁移。双方2024年已在佐治亚州开展机器人即服务合作，公司称累计搬运超过10万个料箱，但新增站点尚未上线。", "analysis": "合作范围从既有单站走向多站复制是积极信号，但新增机器人数量、合同金额、单次成本和人工接管率未披露，暂时无法判断复制效率。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/gxo-and-agility-robotics-expand-partnership-to-accelerate-deployment-of-humanoids-in-u-s-operations"}]}, {"title": "国内新品｜睿尔曼推出GEN62桌面级六轴机械臂", "date": "2026-10-26报道，具体发布日未披露", "body": "据智东西转述发布资料，GEN62面向轻载自动化、具身研发与教学，自重3.5kg、额定负载2kg，工作半径660mm，重复定位精度±0.1mm。产品采用全谐波传动，可选控制器底座集成或分体方案，沿用同平台软件与开发接口，价格仅称万元级。", "analysis": "较低自重和统一开发接口有利于桌面集成，但全臂展最大负载3.5kg不能替代额定负载口径，交期、精确报价、持续负载与耐久性仍待验证。", "sources": [{"label": "智东西原文", "url": "https://zhidx.com/news/43264.html"}]}, {"title": "海外新品｜Realbotix发布Echo社交机器人并开放预订", "date": "2026-10-26", "body": "Echo提供桌面版和全身版，整机价格分别为11950美元和59950美元，199美元只是订金；操作管理服务月费19.99美元起。公司计划2027年下半年首批交付225台桌面版和25台全身版，主要定位陪伴、教育及社交交互，并非自主家务机器人。", "analysis": "机价之外还需计入必需订阅和选配费用；目前仍是预订，调用云服务时必要内容可能传给服务商，不能把本地存储表述理解为全部数据不出设备。", "sources": [{"label": "Realbotix公告", "url": "https://realbotix.ai/news/realbotix-launches-echo-humanoid-robot-line"}, {"label": "BusinessWire厂商通稿全文", "url": "https://www.tmcnet.com/usubmit/-realbotix-launches-echo-humanoid-robot-line-/2026/10/26/10469405.htm"}]}, {"title": "国内研究｜CO01尝试让机器人从本轮失败中即时调整", "date": "2026-10-26报道；官方博客标注2026年10月", "body": "可可矩阵CO01把示范、失败记录和即时指导直接放入上下文，由上层模块挑选经验、动作模型决定下一步，无需为当前任务重新更新权重。厂商真机测试选取首次易失败的任务，每项最多尝试5次，保留自身历史累计成功84%，无历史56%；这不是单次成功率。", "analysis": "这可能帮助现场纠错，但任务数、总试次和可下载代码尚未核验完整；长任务仍会积累误差，示范可能选错，上下文内新技能也不会自动保存到模型权重。", "sources": [{"label": "COCO Matrix技术博客", "url": "https://www.ccmtrx.com/research/co01"}, {"label": "机器之心署名分发", "url": "https://m.sohu.com/a/1092998070_129720"}]}, {"title": "算法研究｜LogLook按需查看历史，减少机器人记忆开销", "date": "2026-10-23预印本；近期研究", "body": "LogLook让系统保留执行日志和旧笔记，由GPT-6 Astra选择要看的图像。RoboMME仿真基准含16项桌面任务、共800测试回合；相同提示、预算和运动规划器下，相比反复重写笔记，成功率相近，模型处理的token（词元）减少43%，图片不到一半。", "analysis": "模型输出路点仍由运动规划器执行，依赖深度和相机标定；调用期间仿真暂停，尚无真机验证，不能把词元节省等同实际时延改善或取代视觉—语言—动作模型。", "sources": [{"label": "arXiv预印本", "url": "https://arxiv.org/abs/2610.32348"}, {"label": "论文实验与限制", "url": "https://arxiv.org/html/2610.32348v1"}]}], "followups": ["待G2 Max披露客户验收、价格、接管率和长时运行数据后复查；Genie Master仅在出现正式材料后纳入。", "跟踪GXO新增站点首批验收，以及Echo正式销售条款和首批交付，核对部署数量、选配费用与完整使用成本。", "待CO01公布完整任务规模或代码、LogLook出现真机和延迟复现后，再按相同任务与预算比较改进幅度。"], "coverage": "覆盖2026-10-26 11:27至2026-10-27 10:35（UTC+8）；LogLook补入10月23日近期研究，保留原始日期。重点公众号公开入口仍有滞后与访问缺口，不代表完整订阅。"}, {"date": "2026-10-26", "edition": "6条 · 产品产业4条／研究2条 · 延迟发送", "updated": "11:27", "intro": "NEURA新一代本体已进入训练设施，智元把训练、任务编排与多机运营整合为平台；相较此前的规划公告，本期出现了设施启用和平台正式发布。启元新增开发者计划与广州体验中心试营业。我们的判断是，竞争正在扩展到任务开发和用户触达，但试运营、研究演示仍不能代替长期成本和可靠性验证。", "items": [{"title": "海外新品｜NEURA推出4NE1 Gen 4，并启用逾2300平方米机器人训练设施", "date": "2026-10-22（近期重要补漏）", "body": "NEURA与慕尼黑工业大学在慕尼黑机场附近启用超过2300平方米的RoboGym，并发布4NE1 Gen 4。厂商称新机较前代轻20%，采用更纤细的结构、织物外皮和支持局部反射控制的Smart Limbs；Neuron AI融合视觉、触觉、力、声音及本体状态。新机已在该设施运行，量产仍在准备中。", "analysis": "训练设施与本体同步推出，有望缩短采数和迭代周期；绝对重量、价格、客户交期及长期任务数据尚未披露，量产准备不等于批量交付。", "sources": [{"label": "NEURA Robotics官方新闻页", "url": "https://neura-robotics.com/tum-robogym-munich-4ne1-gen4-launch/"}]}, {"title": "国内平台｜智元正式发布Genie Studio 2.0，打通任务开发与多机运营", "date": "2026-10-23", "body": "Genie Studio 2.0是一体化具身任务平台：Flywheel覆盖数据、训练、仿真和评测，Agent编排导航定位、推理及业务逻辑，Monitor负责多机状态、调度、告警和远程干预，并将异常数据回流训练。公司案例称，常州六台数控机床上下料项目从需求到产线验证用时14天。", "analysis": "统一平台可能减少交付中的工具拼接工作；14天案例为厂商自述，尚缺独立的成本、接管率和持续运行数据。", "sources": [{"label": "42HOW报道", "url": "https://test.42how.com/en/article/1631d33f-fed8-49b3-bf6a-6599275adc57"}]}, {"title": "国内生态｜启元开放开发者计划，广州金融城体验中心试营业", "date": "2026-10-24至25日；周末重要进展", "body": "启元24日发布“物理AI启仔计划”，提供开发平台、工具和算力支持，征集技能、交互人设及场景方案，开发者社区已上线。新浪财经25日报道，其位于尚品宅配广州金融城总部的体验中心开始试营业，展厅约800平方米，展示Q1、T1并提供改装与编程体验。", "analysis": "开发者供给与线下体验同步扩展，可能帮助验证家庭用户需求；算力额度、收费及许可尚不明确，试营业也不等于新增交付或家庭任务已可稳定自主完成。", "sources": [{"label": "新浪财经快讯", "url": "https://finance.sina.com.cn/7x24/2026-10-24/doc-iniwhxpq8097529.shtml"}, {"label": "金融城体验中心试营业报道", "url": "https://finance.sina.com.cn/roll/2026-10-25/doc-iniwmxsn2967156.shtml"}]}, {"title": "海外供应链｜FANUC将人形机器人零部件列入需求驱动因素", "date": "2026-10-23", "body": "FANUC截至9月30日的半年业绩说明显示，工厂自动化需求受到中国市场带动，中国机床需求强劲；人形机器人零部件与人工智能数据中心、半导体及新能源汽车一道，被列为需求驱动因素。这是供应链景气度的公司层面信号，并非人形整机产品发布。", "analysis": "披露说明人形机器人需求已进入头部自动化厂商的经营观察范围，但公司未单列相关收入、订单或终端装机量，不能把集团增长整体归因于人形机器人。", "sources": [{"label": "FANUC官方半年业绩说明", "url": "https://www.fanuc.co.jp/en/ir/announce/pdf/2026/reference202609_e.pdf"}]}, {"title": "国内研究｜λ0用人类示范训练机器人边走边操作", "date": "10月13日预印本、21日修订；近期研究", "body": "阿里巴巴Token Hub与高德团队提出λ0，将人类第一视角视频与全身、手部运动数据进行视角和动作对齐，用于训练人形机器人的全身移动操作；最后阶段仍加入原生机器人演示和任务对齐数据。在宇树G1四项真机任务中，每种方法合计测试40次，λ0完成率为62.5%，π0.5为40%。", "analysis": "这一路径可能降低全身操作数据完全依赖机器人遥操作的成本，但样本量有限，且仍依赖身体控制器和机器人后训练，不能解读为仅凭人类视频即可直接部署。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.18950"}, {"label": "λ0项目页", "url": "https://lambdahumanoid.github.io/"}]}, {"title": "国内研究｜HandsOn检验灵巧操作，仿真任务仍有明显失败", "date": "10月19日预印本；10月26日报道，近期研究", "body": "清华等团队发布HandsOn仿真平台，包含66项人工验证任务和1.8万条仿真遥操作示范，并区分有示范的Core-50与无目标任务训练示范的Transfer-16。最佳受训多任务策略在Core-50成功率为29.1%；未经基准微调的GPT-6通过move_eef工具控制手掌和手指，在同组任务中成功率为5.2%。", "analysis": "该基准可定位接触、双手配合与目标保持中的失败；模型训练条件不同，结果不构成同预算比较。这里测的是仿真，真机仅有定性演示，不能外推实际部署或替代关系。", "sources": [{"label": "arXiv论文", "url": "https://arxiv.org/abs/2610.26765"}, {"label": "HandsOn官方代码库", "url": "https://github.com/TsinghuaC3I/HandsOn"}]}], "followups": ["G2 Max正式材料出现后核对新增能力、价格和交付；H2-X有完整演示原片或厂商回应后再核验事故原因与可靠性。", "NEURA与Genie Studio披露客户验收或长时运行数据时，复查接管率、任务成本和连续稳定性。", "启元公布开发者许可、算力额度及门店成交/交付数据时，复查开放范围与实际家庭使用反馈。"], "coverage": "覆盖2026-10-23 10:45至2026-10-26 11:27（UTC+8），完整回溯周末；补入10月22日NEURA新品及两项近期研究，保留真实事件日期。重点公众号公开入口存在滞后和访问缺口，不代表完整订阅。今日延迟发送。"}, {"date": "2026-10-23", "edition": "9条 · 产品产业6条／研究3条", "updated": "10:45", "intro": "宇树H2-X是一次新型号发布，本期补入10月21日的重要进展；现有展示仍不能代替实际作业和交付验证。MaxLoop、Humanoid机载整合及Cosmos巡检数据流程，分别推进采集反馈、设备集成和训练准备；我们的判断是，这些配套环节值得关注，但仍需用真实任务成本与接管率验证收益。", "items": [{"title": "国内新品｜宇树发布H2-X，展示新型号运动能力", "date": "2026-10-21；近期重要补漏", "body": "中国证券报报道，宇树通过“功夫传奇”视频正式发布H2-X，展示从4米平台落地、武术动作以及安保和救援场景。厂商称其站立工况续航约8小时，但未披露售价、交期及独立重复测试结果；该指标也不代表连续作业时长。", "analysis": "新型号扩大了运动能力展示范围；安保、救援仍属视频场景，实际自主程度、动作重复性和负载工况续航还需验证。", "sources": [{"label": "中国证券报报道", "url": "https://finance.eastmoney.com/a/202610213902709325.html"}]}, {"title": "海外采数｜Maxinsights推出MaxLoop，研发触觉采集手套", "date": "2026-10-22", "body": "Maxinsights发布MaxLoop质量反馈平台，称可把采数评分与纠正反馈缩短至同日。公司披露累计采集逾200万小时，其中150万小时已整理为训练可用数据，并与Genesis AI联合开发MaxGlove触觉手套；后者目前仍处研发阶段。", "analysis": "同日反馈可能缩短数据返工周期，但采集量不等于交付量，独立训练收益和成本仍待验证。", "sources": [{"label": "Maxinsights公司新闻稿", "url": "https://www.businesswire.com/news/home/20261022672609/en/"}, {"label": "量子位报道", "url": "https://www.qbitai.com/2026/10/504800.html"}]}, {"title": "海外硬件｜Humanoid把两台机载计算机整合为一台Thor", "date": "2026-10-21；近期进展", "body": "Humanoid宣布扩大与NVIDIA合作，下一代机器人架构将原有两台机载计算机整合为一台Jetson Thor，厂商称可维持原有计算能力。方案同时结合Isaac OS与Holoscan传感器数据链路，以减少中央处理器和图形处理器之间的数据复制。", "analysis": "硬件整合有望降低系统复杂度，但公告没有整机功耗、端到端时延及任务成功率对比，也不代表已经量产供货。", "sources": [{"label": "Humanoid官方公告", "url": "https://thehumanoid.ai/humanoid-expands-collaboration-with-nvidia-to-power-its-next-generation-of-humanoid-robots/"}]}, {"title": "海外设施｜Generative Bionics规划意大利机器人训练基地", "date": "2026-10-21；近期进展", "body": "Generative Bionics与AMD合作规划三个机器人训练基地。首个意大利基地计划占地5000平方米，目标于2027年第四季度启用，将GENE.01真实工业操作、数字孪生和AMD算力结合，先在基地训练，再进入客户环境验证。", "analysis": "集中训练设施可能加快工业任务迭代，但当前仍是建设计划；投资额、机器人数量及另外两处基地信息均未披露。", "sources": [{"label": "Generative Bionics官方公告", "url": "https://news.gbionics.ai/?article=data-factory&lang=en"}]}, {"title": "国内供应链｜图达通与伽利略合作开发机器人感知系统", "date": "2026-10-21；近期进展", "body": "图达通与伽利略签署战略合作协议，计划把激光雷达感知能力与机器人平台结合，目标场景包括电力巡检、安防、末端配送及应急救援。伽利略提供的平台覆盖可变构型、四足和人形机器人，但公告未列出具体雷达型号。", "analysis": "合作扩大了激光雷达面向机器人场景的验证入口，但战略协议不等于供货订单，采购数量、收入和验收结果均未知。", "sources": [{"label": "图达通署名合作公告", "url": "https://www.ne-time.cn/web/article/40080"}]}, {"title": "海外工具｜Cosmos增加数据生产流程，ANYbotics用于巡检训练", "date": "2026-10-21；近期进展", "body": "NVIDIA为Cosmos增加训练工具、仿真检查点和Data Factory蓝图。ANYbotics已用相关流程生成超过1500段合成视频，并通过Encord验证输出，用于训练工业巡检机器人识别液体泄漏等环境变化；这些片段并非真实部署工时。", "analysis": "工具链开始进入具体巡检训练流程，但实际误报率、训练成本及现场收益未披露，合成数据规模不能替代业务验证。", "sources": [{"label": "NVIDIA官方工具与应用说明", "url": "https://blogs.nvidia.com/blog/cosmos-open-train-evaluate-deploy-world-models/"}]}, {"title": "国内研究｜智元第四期数据集增加任务推理过程", "date": "2026-10-22", "body": "AGIBOT WORLD 2026第四期Physical Reasoning发布，覆盖9类推理和3档难度，增加数量、遮挡、位置占用及任务进度变化，例如补货前统计已有物品、寻找物体时记录已检查抽屉。官方数据仓库已出现对应目录。", "analysis": "增加任务状态变化，有助于研究何时采取哪种动作；尚无统一下游成功率增益，仓库采用CC-BY-NC-SA非商用许可。", "sources": [{"label": "文汇报发布报道", "url": "https://www.jfdaily.com/staticsg/res/html/web/newsDetail.html?id=1199086"}, {"label": "官方数据目录与许可", "url": "https://huggingface.co/datasets/agibot-world/AgiBotWorld2026/tree/main/PhysicalReasoning"}]}, {"title": "国内研究｜CEL让机器人从同伴成功操作中改进", "date": "论文2026-10-19首发、10-21修订；10-22报道", "body": "清华、智元等的CEL预印本先用专家数据初始化策略，再由失败场景检索机器人群中的成功片段来更新。96台机器人参与手机包装训练后，在未参与采集的机器人上测试120次，成功率由79.2%提升至98.3%。", "analysis": "群体经验可帮助修复失败，但仍需人工标记成败、重置环境；实验限于同一平台，增加机器人也增加总数据，并非同预算比较。", "sources": [{"label": "CEL预印本v2", "url": "https://arxiv.org/abs/2610.25736"}]}, {"title": "海外研究｜OpenTac用可定制触觉皮肤改善接触操作", "date": "2026-10-22预印本；10-23索引", "body": "OpenTac提出可定制电阻式触觉皮肤，通过凸起结构感知压力和剪切，并开放设计、读出硬件和软件。SO-101真机在无视觉插头插入任务中，各条件使用100次示范、测试50次；触觉加关节信息成功率为62%，仅关节基线为36%。", "analysis": "触觉改善了接触操作，但凸起也改变接触力学，增益不能全归于剪切信号；材料存在漂移与迟滞，长期工业寿命尚未验证。", "sources": [{"label": "OpenTac预印本", "url": "https://arxiv.org/abs/2610.31661"}, {"label": "实验与代码入口", "url": "https://opentac.github.io/results/"}, {"label": "OpenTac代码", "url": "https://github.com/opentac/opentac"}]}], "followups": ["H2-X公布售价、交期或独立测试时，复查重复动作、负载下续航及自主程度。", "智元Genie Studio 2.0正式发布后核对能力与开放范围；数据集须进一步检查文件完整性和使用许可。", "训练基地启用、感知合作落单及巡检现场测试出现时，核对采购量、验收结果、误报与接管成本。"], "coverage": "检索覆盖2026-10-22 10:39至2026-10-23 10:45（UTC+8），并补入10月21日未报重要进展及近期CEL研究。公众号公开入口存在滞后与访问缺口，未声称完整订阅。"}, {"date": "2026-10-22", "edition": "7条 · 产品产业6条／研究1条", "updated": "10:39", "intro": "墨宝正式开放预订，特斯拉披露Optimus开始产线生产，但两者分别仍缺交期和爬坡产量，不能等同于批量交付。武汉零售仓已有运营订单；判断这类项目能否复制，还需要接管与维护成本。Isaac工具更新、S1采数手套和Flora标注模型分别补足开发、采集和整理环节，显示机器人产品之外的配套工具也在持续推出。", "items": [{"title": "国内新品｜墨宝正式发布，面向家庭陪伴开启预订", "date": "2026-10-21", "body": "墨甲在芜湖发布0.9米、22个自由度的墨宝并开启全球预订，功能覆盖儿童识物问答、故事与英语互动、长辈陪聊提醒，以及家庭成员识别和记忆。现场35名天使用户获得一年免费体验，这不属于付费交付量；MoAgent演示了接收临时问询后继续执行任务。", "analysis": "家庭成员识别和长期记忆让产品定位更具体；后续需看真实家庭使用反馈、最终售价与交付安排，免费体验不代表已完成商业验证。", "sources": [{"label": "墨甲正式发布公告", "url": "https://www.prnasia.com/story/552626-1.shtml"}]}, {"title": "海外制造｜特斯拉称Optimus已在弗里蒙特产线开始生产", "date": "美国10月21日财报；北京时间10月22日", "body": "特斯拉第三季度官方更新称，弗里蒙特高产量设计产线已开始生产Optimus，产出的是公司首批生产级机器人。更新文件的产能表将加州Optimus状态列为“早期爬坡”，得州产线仍在建设中，两处均未填写机器人产能数字，硬件和制造流程还将继续迭代。", "analysis": "生产级机器人下线说明进入产线爬坡阶段，但不等于已经达产或客户批量交付。后续应核对实际产量、良率、单位成本和运行表现。", "sources": [{"label": "特斯拉Q3官方更新第5页", "url": "https://assets-ir.tesla.com/tesla-contents/IR/TSLA-Q3-2026-Update.pdf"}]}, {"title": "国内落地｜智元披露武汉江滩零售仓运营订单", "date": "10月20日披露；截至10月19日数据，近期重要补漏", "body": "智元、武汉文旅集团和中云微迅合作，在汉口江滩江遇桥墩电影营地部署远征A3 Ultra，承担零食饮品识别、抓取和交付。厂商披露，截至10月19日设备连续运营18天、每天约8小时，累计完成827单，覆盖十余款商品，抓取环节成功率超过97%。", "analysis": "连续订单比单次演示更接近真实运营，但抓取成功率不等于端到端履约率。人工接管、补货维护成本和利润均未披露，不能据此认定无人化。", "sources": [{"label": "投资界刊载项目披露", "url": "https://news.pedaily.cn/202610/570563.shtml"}]}, {"title": "海外平台｜Isaac更新开发工具，Agile ONE SN计划明年供货", "date": "2026-10-21", "body": "NVIDIA与Agile Robots公布Agile ONE SN参考人形机器人，设备预装Isaac GR00T并搭载Jetson Thor，试图把数据采集、仿真、训练和部署接入同一流程，计划于2027年初提供。同期，Isaac Lab 3.0正式可用，Isaac OS推出首个公开测试版。", "analysis": "平台整合有望减少开发者拼装工具的工作。软件已推出，参考整机则计划2027年初提供；价格、实际提效和安全集成效果仍待验证。", "sources": [{"label": "NVIDIA官方平台发布", "url": "https://blogs.nvidia.de/nvidia-advances-isaac-platform-for-general-purpose-robotics/"}]}, {"title": "海外应用｜Bear发布KINO-2，连接示范学习与搬运流程", "date": "2026-10-21", "body": "Bear发布KINO-2机器人学习平台，可把人类任务示范转成KR1操作技能，并支持自研模型和外部基础模型，当前用于超市退货及仓储料箱操作试点。公司称，经Isaac OS、TensorRT和量化联合优化，内部测试中的GR00T推理时间由未优化部署时约500毫秒降至约60毫秒。", "analysis": "推理时延下降可能改善动作响应，但数据仅对应特定内部系统，不能归因于单一软件。试点规模、人工接管率和端到端任务成功率尚未披露。", "sources": [{"label": "Bear产品与工程公告", "url": "https://fl.bearrobotics.ai/blog/bear-robotics-launches-kino-2"}]}, {"title": "海外采数｜Origami S1手套同步记录手指动作与触觉", "date": "2026-10-21发布", "body": "Origami S1手套以编码器记录20个手指关节角度，并同步采集指尖和手掌压力、腕部视频，在手指被遮挡时仍可保留动作数据。其关节结构与公司自研机器人手对应，软壳用于适配不同手型。公司称产品已开始量产，但使用前仍需针对每名采集者调整和校准。", "analysis": "动作与触觉同步可减少灵巧手数据对纯视觉的依赖，但人机指尖形状及接触压力仍有差异。售价、出货时间和跨用户耐久性尚未公布。", "sources": [{"label": "Origami技术与产品说明", "url": "https://www.origami-robotics.com/blog/a-million-hours-of-what"}]}, {"title": "海外研究｜Flora把操作视频转成可筛选、可评分的训练数据", "date": "10月20日对外介绍、10月21日报道；模型卡标注10月15日，近期研究", "body": "NVIDIA Flora把操作视频切成动作片段、生成说明并评价执行质量，供数据筛选和强化学习使用，输出是标注而非机器人动作。团队称512张GB300每天可标注20万小时视频，这是处理吞吐；与GPT-6 Astra比较仅针对机器人标注，指标互有胜负。", "analysis": "方法可能降低大规模视频整理成本，但结果仍来自团队基准，尚无独立生产任务收益验证。Captioner和Rewarder模型卡限定为非商用研究开发用途。", "sources": [{"label": "NVIDIA研究项目与论文入口", "url": "https://research.nvidia.com/labs/gear/flora/"}, {"label": "Captioner模型卡与许可", "url": "https://huggingface.co/nvidia/Flora-Captioner"}]}], "followups": ["跟踪墨宝最终零售价、付费订单和实际交付时间；复查武汉零售仓端到端履约率、人工接管频次及补货维护成本。", "跟踪Optimus早期爬坡的实际产量、制造良率、单位成本和对外交付证据；在官方披露前不把产线启动写成规模达产。", "等待智元自10月22日起七个工作日内的新品系列正式结果，并核验11月2日至3日六台G2便利店24小时直播的完整记录、接管情况和失败类型，不把计划写成已发生。"], "coverage": "检索覆盖2026-10-21 10:33至2026-10-22 10:39（UTC+8）；另补入10月20日披露的武汉运营数据及近期Flora研究。重点公众号公开入口存在索引滞后，未声称完整订阅。"}, {"date": "2026-10-21", "edition": "6条 · 产品产业4条／研究2条", "updated": "10:33", "intro": "制造端出现两种不同进度：舍弗勒已让6台人形机器人进入关节组件工厂，AGCO则把Digit试点安排到2027年，但两者均未披露接管率或效率验收结果。家庭机器人开始用可退款预约测试需求，不过Voxel计划2028年交付，现阶段仍属开发原型。两项研究都尝试降低机器人适配新本体或接触任务的门槛，但证据分别受本体条件和纯仿真验证限制。", "items": [{"title": "国内落地｜舍弗勒太仓工厂让人形机器人组装关节", "date": "2026-10-20公告", "body": "舍弗勒宣布启用太仓约7500平方米人形机器人灯塔工厂，涵盖零部件制造、训练采数和数字孪生。6台人形机器人已在5个工位参与备料分拣、装配、检测及包装，工厂开始量产直线和旋转执行器等关节组件；这不是完整人形机器人整机制造。", "analysis": "机器人参与生产自身上游组件，为工艺和训练数据闭环提供了真实场景；但节拍、良率、人工接管率及回本周期均未披露，不能据此判断无人化或效率提升。", "sources": [{"label": "舍弗勒公告", "url": "https://www.schaeffler.de/en/news_media/press_releases/press_releases_detail.jsp?id=88222851"}]}, {"title": "海外落地｜AGCO签约引入Digit，2027年开始工厂试点", "date": "2026-10-20", "body": "农机制造商AGCO与Agility Robotics签署商业协议，计划2027年在美国堪萨斯州Hesston工厂试点Digit。初期任务包括零件分拣堆叠和料箱存放，公告同时介绍了配套的Arc车队管理平台。应用范围是农机制造厂内部，并非让人形机器人进入田间作业。", "analysis": "协议把Digit扩展至农机制造场景，但台数、金额和试点周期尚未公布；减轻劳动负担、提高效率仍是项目目标，而非已经通过验收的结果。", "sources": [{"label": "Agility与AGCO公告", "url": "https://www.agilityrobotics.com/content/agco-and-agility-robotics-advance-smart-manufacturing-with-humanoid-robot-pilot-in-hesston-kansas-facility"}]}, {"title": "海外新品｜Voxel开启家庭机器人预约", "date": "2026-10-20发布；2026-10-21核验官网", "body": "Tuesday Labs发布双足家庭机器人Voxel，定位收拾和查找物品、取物及照料植物。美国用户可支付200美元预约，正式下单前可退款；预计整机2万美元，最终价未定，计划2028年起交付。预约协议明确：当前仍是开发原型，交付前可能大幅改版，时间也可能延后。", "analysis": "可退款预约更接近需求测试，而非现货销售或量产证明。跨家庭环境成功率、人工辅助比例，以及儿童宠物安全、隐私处理等关键指标仍未披露。", "sources": [{"label": "产品官网", "url": "https://tuesdaylabs.com/robot"}, {"label": "预约与产品阶段条款", "url": "https://tuesdaylabs.com/reservation-terms"}]}, {"title": "国内供应链｜智微智能披露Thor控制器新增智元客户", "date": "2026-10-20投资者活动记录", "body": "智微智能在投资者活动记录中称，智擎Thor机器人大脑控制器新增智元合作客户，并进入其首批A链供应商，同时与优必选联合开发。公司产品覆盖大脑、小脑及大小脑一体控制器，并表示一体化方案有助于降低成本、缩小设备体积。", "analysis": "披露显示控制器供应商正争取整机客户协同开发，但目前仅有上市公司单方陈述；订单金额、出货规模和实际降本比例均未公开，客户关系仍待交叉确认。", "sources": [{"label": "智微智能投资者活动记录原文", "url": "https://vip.stock.finance.sina.com.cn/corp/view/vCB_AllBulletinDetail.php?id=12650680&stockid=001339"}]}, {"title": "海外研究｜Dream-1尝试把操作能力复用到新机器人", "date": "2026-10-19海外发布；近期重要补漏", "body": "Dream Labs发布Dream-1世界动作模型并开放应用程序接口，起价为每小时3美元。模型联合预测视频和动作，给出夹爪目标位置及开合状态，再由各机器人自身的逆运动学求解器转换为关节动作。厂商展示了27种未见仿真本体和4种真实本体的零样本评测。", "analysis": "对双臂平行夹爪，这种接口可能减少适配成本；但依赖本体求解器，末端目标不保证整臂绕障路径可行。每小时起价也不是每次任务成功的总成本。", "sources": [{"label": "Dream Labs技术说明与API入口", "url": "https://dreamlabs.ai/research/dream-1/"}]}, {"title": "国内研究｜TacTalent把触觉变成图像，测试Astra接触操作", "date": "10月19日UTC提交，预印本；近期补漏", "body": "清华与高德作者把视觉式触觉图像输入Astra，用少量成功演示引导操作。两套基准共19项任务，每种输入设置采样210个仿真场景，多数任务仅10次。UniVTAC视触觉平均成功率93.8%，纯视觉76.3%；尚未验证真机，不能直接推论全面超过专用策略。", "analysis": "该方法可能让通用模型利用接触信息，但视触觉完整接口响应中位14秒，含等待、不含仿真执行；一轮可给多个动作，仍需验证真实接触与控制延迟。", "sources": [{"label": "论文全文", "url": "https://arxiv.org/html/2610.26846v1"}, {"label": "作者代码", "url": "https://github.com/ccyydd/TacTalent"}]}], "followups": ["核验墨宝2026-10-21发布活动的正式结果，重点记录产品形态、价格、交付时间及演示是否为真机连续运行。", "补看NEURA在GTC的完整演示，区分模型直接输出动作、调用预制技能与人工遥控，并确认本体和任务条件。", "持续追踪舍弗勒、AGCO等工厂项目的人工接管率、任务节拍、良率及连续运行时长；任一指标公开后复查商业化判断。"], "coverage": "检索覆盖2026-10-20 10:33至2026-10-21 10:33（UTC+8）；另补入Dream-1和TacTalent近期重要研究，均非今日新发布。公众号公开入口存在更新滞后，未声称完整订阅。"}, {"date": "2026-10-20", "edition": "6条 · 产品产业4条／研究2条 · 延迟补发", "updated": "10:33", "intro": "本期延迟补发，新闻检索截止于今日10:33（UTC+8）。乐聚与兆丰的15台机器人上料项目提供了产线应用证据，但30多秒节拍与未来15秒目标仍需分清；这是此前漏收的重要进展。Figure转向长时行走压力测试，通用模型研究则暴露精密接触与耗时限制：判断可用性，需要把任务表现、人工介入和连续作业条件一起看。", "items": [{"title": "国内落地｜乐聚与兆丰将15台夸父用于产线上料", "date": "2026-10-15发布，10月16日报道；近期重要补漏", "body": "兆丰官网确认与乐聚发布小件上料方案并揭牌示范基地，向OpenLET社区捐赠真机在环数据。第一财经记者在厂内看到15台夸父分布于不同工位，单次动作需30多秒；报道给出的98%作业成功率属于报道及项目方口径。兆丰董事长称，抓零件曾做约1.5万次训练。", "analysis": "半年至一年压缩至15秒只是目标。缺少失败、接管和长期验收日志，现阶段不能推导回本周期或全面替代人工。", "sources": [{"label": "兆丰官方公告", "url": "https://www.hzfb.com/news/newsinfo/379.html"}, {"label": "第一财经现场采访", "url": "https://www.yicai.com/news/103397266.html"}]}, {"title": "国内新品｜PhyHand全直驱灵巧手亮相广交会", "date": "2026-10-15至19日广交会一期；10月18日现场报道", "body": "界面新闻现场报道，动易科技首发PhyHand系列全直驱拟人灵巧手，配置23个主动自由度，现场演示石头剪刀布；公司还展示PHYBOT D工业巡防方案。其市场负责人称，海外采购商更希望获得综合解决方案，而不只是观看机器人本体动作。", "analysis": "23自由度是结构规格，手势演示也不能证明精密装配能力。定价、交付期、抓力、触觉与耐久数据均未核验。", "sources": [{"label": "界面新闻现场报道", "url": "https://www.jiemian.com/article/15203405.html"}]}, {"title": "海外本体｜Figure 03披露九天行走压力测试", "date": "2026-10-19厂商更新及媒体报道", "body": "Humanoids Daily与Interesting Engineering转述Figure创始人Brett Adcock称，Figure 03在跑步机上的行走测试已持续9天，累计348英里、约560公里和120万步，发布消息时测试仍在继续。测试目的为通过重复行走暴露潜在硬件故障。", "analysis": "数据属于媒体转述厂商自述，并非独立耐久验证；协议、维护、供电和人工介入均未披露，也不代表单次充电运行九天。", "sources": [{"label": "Humanoids Daily转述厂商更新", "url": "https://www.humanoidsdaily.com/news/figure-03-nine-day-treadmill-million-steps"}, {"label": "Interesting Engineering报道", "url": "https://interestingengineering.com/ai-robotics/figure-03-humanoid-robot-treadmill-test"}]}, {"title": "海外市场｜FR-NIA以可定制表情切入陪伴机器人", "date": "2026-10-19报道；官网计划10月20日启动众筹", "body": "Figurobot官网展示FR-NIA表情陪伴机器人，头部共10个自由度，包括颈部3个、面部7个；配套应用支持录制动作、调整关键帧和自定义表情。截至检索时，官网仍处预约阶段：支付20美元可锁定699美元众筹价，支付1美元对应799美元。", "analysis": "预约不等于购买或交付，产品款和运费仍需另付。长期互动记忆、任务效果及最终交付时间尚无可核验证据。", "sources": [{"label": "Figurobot官方规格与预约条款", "url": "https://us.figurobot.com/"}]}, {"title": "国内研究｜会抓取仍难插装：Astra真机评测呈现任务差异", "date": "2026-10-15 UTC提交；近期专题补漏，预印本", "body": "《Has GPT-6-Astra Achieved Embodied Intelligence?》覆盖12项基准和8种真机配置。真机实验中，刚性抓放18次、成功17次；三个平台的插头插入合计11次、成功0次。Astra负责慢速高层判断并经控制接口输出动作，没有替代底层实时控制。", "analysis": "真机有人工编写的工具与安全上下文，操作者全程持急停；仿真还允许读取演示并延长步数。样本较小，不能据此作同预算胜过专用策略的结论。", "sources": [{"label": "论文全文及真机实验", "url": "https://arxiv.org/html/2610.22471v1"}]}, {"title": "海外研究｜把探索保存为程序：RAX减少重复决策开销", "date": "2026-10-15 UTC提交；近期专题补漏，预印本", "body": "《Scaling Online Exploration for Robot Agents》让冻结的编程智能体通过控制与视觉接口探索，再写成程序和可复用技能，无需遥操作动作演示或策略训练。Franka操作空气炸锅的案例中，编译后程序计算耗时18秒，机器人动作耗时2.5分钟；18秒并非完整任务时间。", "analysis": "探索期曾撞相机触发安全停止，也有操作员重置与调整物体。程序复用可能减少重复计算，但需验证布局变化和异常恢复，不能称全程无人。", "sources": [{"label": "论文全文（表9及附录14.2）", "url": "https://arxiv.org/html/2610.22496v1"}, {"label": "作者公开代码", "url": "https://github.com/robot-agent-exploration/rax"}]}], "followups": ["跟踪乐聚与兆丰方案的实际节拍、换型时间、接管频率及长期验收数据；出现独立运行日志后复查商业可行性。", "核验FR-NIA正式众筹价格、交付承诺，并跟进10月21日墨宝发布；预约或预告不作为上市、交付结果。", "继续观察Astra与RAX在不暂停环境中的接触验证、端到端总耗时、布局变化适应及人工恢复次数。"], "coverage": "覆盖窗口为2026-10-19 11:10至10月20日10:33 UTC+8，并补回乐聚与兆丰、PhyHand及两篇10月15日提交的重要研究。具身智能之心公开入口可见内容更新至9月30日，存在滞后；新智元公开流不足以确认完整覆盖；量子位相关赛事原文存在访问缺口。启元金融城店尚无新开业证据，未把旧预告写成结果。"}, {"date": "2026-10-19", "edition": "6条 · 产品产业5条／研究1条 · 周末回溯", "updated": "11:10", "intro": "本期延迟发送，汇总周末进展并补入两条此前未收录的重要消息。UniUni和RP1分别把表演编队与机器人研发的工具链做得更完整，采购时仍需验证现场稳定性和可复现程度。Plim、墨宝与FF Nova呈现家务陪伴、交互陪伴和开发教育三种定位，当前不能用功能展示代替交付与任务表现。", "items": [{"title": "国内产品｜宇树发布UniUni集群控制工具", "date": "2026-10-16发布｜周末回溯", "body": "据宇树产品资料，UniUni支持G1、H2及Windows、macOS，可绘制二维和三维轨迹、按时间线编排动作，并提供点云建图定位、温度异常监测、急停、动作库和自然语言编排。运营者可把编队设计与现场设备监控放在同一桌面工具中。", "analysis": "这有望减少编队表演的准备工作，但仍需现场验证同步误差、断网恢复和实际人力节省；不能推定它已支持任意工业多机任务。", "sources": [{"label": "宇树官方产品页", "url": "https://uniuni.unitree.com/"}, {"label": "新浪科技发布日期", "url": "https://finance.sina.com.cn/jjxw/2026-10-16/doc-inivmazq1643049.shtml"}]}, {"title": "国内产品｜RP1公开从硬件到训练部署的开发栈", "date": "2026-10-16发布材料｜周末回溯", "body": "RP1曾于9月28日在IROS亮相，本次增量是发布开源平台与公开仓库。总仓列出机械CAD、电路PCB与物料清单、装配文档、关节固件、机器人模型及训练部署子仓入口，并支持24、28、30和42自由度配置。", "analysis": "分层资料便于团队审查和修改研发平台；本次未逐文件复现，各子仓版本、许可及硬件配置需分别核对，价格与交付也不能从开源推定。", "sources": [{"label": "RoboParty官方仓库", "url": "https://github.com/Roboparty/RP1"}, {"label": "公司发布材料", "url": "https://www.europapress.es/comunicados/internacional-00907/noticia-comunicado-acabaron-cajas-negras-roboparty-lanza-rp1-codigo-abierto-pila-completa-20261016110143.html"}]}, {"title": "海外新品｜Plim把自主家务与远程陪伴放进同一产品", "date": "2026-10-17报道｜周末重要进展", "body": "慕尼黑Devanthro已确认更名为Plim Robotics。Plim产品页展示自主家务和Step-in远程操作两种模式，远程模式可呈现操作者的面孔、声音与动作；机器人采用三轮全向底盘和两指夹爪，厂商标称续航两小时并可自动回充。", "analysis": "远程操作提供亲友或护理人员参与的入口，但目前仅登记意向，售价、交付日期、任务成功率和人工接管频次均未披露。", "sources": [{"label": "Plim官方产品页", "url": "https://plim.com/meet-plim"}, {"label": "公司更名公告", "url": "https://www.devanthro.com/devanthro-is-now-plim-robotics/"}]}, {"title": "国内预告｜墨宝预告10月21日首发并开启预订", "date": "2026-10-16公告｜10月21日待发布", "body": "奇瑞墨甲公告将于10月21日在芜湖发布家庭陪伴人形机器人墨宝并开启预订。发布内容预计涉及语言交互、视觉识物、日程提醒、长时记忆和MoAgent；这些仍是功能预告，售价、正式参数及交付计划尚未给出。", "analysis": "产品定位从商用接待延伸到家庭陪伴，但现有材料不能证明其具备家务操作能力，也不能把开启预订等同于现货交付。", "sources": [{"label": "墨甲公司新闻稿", "url": "https://www.prnasia.com/story/552003-1.shtml"}]}, {"title": "海外新品｜FF Nova以2490美元切入开发与教育市场", "date": "2026-10-15公告｜近期补漏", "body": "FF投资者官网列出FF Nova与Nova Mini联合发布。Nova官方商店标价2490美元，具备20个自由度，双足本体约2.8千克并配可拆卸移动底座，同时提供Python软件开发工具包和从仿真到真机的工作流。", "analysis": "其规格和价格更接近科研教育平台而非全尺寸家务机器人；标价不代表包含服务和部署的总成本，实际交付量与任务成功率也未核验。", "sources": [{"label": "FF Nova官方规格与价格", "url": "https://shop.ff.com/products/ff-nova"}, {"label": "FF公司公告目录", "url": "https://investors.ffai.com/press-releases/"}]}, {"title": "海外研究｜让模型记住前序操作：Astra在RoboMME上的能力与边界", "date": "2026-10-12 UTC提交｜近期专题补漏，预印本", "body": "研究使用冻结的GPT-6 Astra直接输出末端路点和夹爪指令，不针对RoboMME训练，并保留完整操作历史。在16项仿真任务、800回合中成功率为92.1%；每次调用平均耗时18.3秒，主要失败包括提前宣告完成及按键时机错误或误按。", "analysis": "该结果提示通用模型可承担部分依赖历史的操作流程，但模拟器会暂停等待调用；不暂停的真机环境下，成功率、成本和安全性仍需重新验证。", "sources": [{"label": "论文全文", "url": "https://arxiv.org/html/2610.17350v1"}, {"label": "作者代码和日志", "url": "https://github.com/jackbjed/embodied-astra-robomme"}]}], "followups": ["10月21日墨宝发布后核对价格、交付安排和功能边界；启元金融城店10月15日试营业目前仍只有旧预告，继续寻找实际开业及交付证据。", "Plim与FF出现实际交付或独立测试后，复查任务成功率、人工接管次数、续航和包含部署服务的总成本。", "UniUni后续重点验证现场网络异常、同步误差与急停机制；Astra研究重点验证环境不暂停时的成功率和动作时延。"], "coverage": "检索覆盖2026-10-16 11:06至2026-10-19 11:10（UTC+8），包含整个周末；另补入10月15日FF产品和10月12日UTC提交的Astra研究，均非今日新发布。重点公众号公开索引有滞后与访问缺口，启元金融城店实际开业和新增交付未获核验。"}, {"date": "2026-10-16", "edition": "6条 · 产品产业4条／研究2条", "updated": "11:06", "intro": "本期延迟发送，合并昨天未发送期间的重要进展。Digit 5确认快充电池技术供应商，把续航竞争延伸到补能停机时间；NOVA21与TOMO则分别瞄准灵巧操作研发和教育互动。两项研究尝试解决接触时让步与移动取物站位问题，仍需区分小规模真机验证和可持续部署。", "items": [{"title": "国内新品｜万拿NOVA21灵巧手", "date": "10月15日发布", "body": "万拿在香港秋季电子产品展发布面向科研开发的NOVA21灵巧手。厂商材料称其具有21个全主动旋转直驱自由度和16个力传感器，覆盖指尖、指腹三维触觉与掌心法向力，并支持力控、反驱、快换手腕及多种控制接口。", "analysis": "较完整的触觉与控制接口有利于科研集成，但现有来源属于商讯转载，价格、耐久性和量产交付均未获独立验证。", "sources": [{"label": "厂商发布材料／界面商讯", "url": "https://www.jiemian.com/article/15194944.html"}]}, {"title": "海外供应链｜Digit 5选择Nyobolt快充电池", "date": "10月15日公告", "body": "Agility宣布为Digit 5选择Nyobolt快充电池技术，目标续航90分钟、充电9分钟，并将运行与充电时间比由Digit 4的2:1提高至10:1。采用该电池的早期客户版本预计2027年上半年可用，随后6至9个月扩大供应。", "analysis": "快充若能在真实负载下成立可明显提升设备利用率，但每日工作时长仍是公司目标，温升、循环衰减和自动回充耗时尚待实测。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/agility-robotics-selects-nyobolt-as-its-ultra-fast-charging-battery-technology-partner-for-digit-5"}]}, {"title": "国内新品｜Rice Robotics推出教育机器人TOMO", "date": "10月15日发布", "body": "Rice Robotics HK发布轮式人形机器人TOMO，配备表情面部、胸前互动屏和两指平行夹爪，定位互动阅读、科学技术工程数学教育、编程及有人监督的机器人探索。Rice Robotics HK同时加入FLAIR平台，合作探索教育与制造场景的训练验证。", "analysis": "这是一款面向互动教学与受监督探索的产品，实际采用仍需核验学校交付、售价及儿童接触安全，不能据发布材料推定可无人值守。", "sources": [{"label": "Axonex公司新闻稿", "url": "https://rss.globenewswire.com/news-release/2026/10/15/3381644/0/en/axonex-ai-group-joins-flair-s-embodied-ai-international-applications-hub-and-launches-education-humanoid-tomo.html"}]}, {"title": "中外合作｜Cerence与吉利将座舱语音能力用于服务机器人", "date": "10月15日公告", "body": "Cerence宣布与吉利把既有智能座舱合作扩展至机器人，并在巴黎车展演示人形机器人的多语言交互，语音识别可同时支持法语、英语和普通话。此次增量主要是将座舱交互技术迁移至服务机器人，而非运动策略或自主操作升级。", "analysis": "成熟座舱语音栈可能缩短多语言交互开发周期，但噪声识别率、端到端时延、动作执行成功率及规模交付均未公布。", "sources": [{"label": "Cerence官方新闻稿", "url": "https://www.globenewswire.com/news-release/2026/10/15/3381290/0/en/cerence-ai-and-geely-advance-human-machine-interaction-through-robotics-technology-services-partnership.html"}]}, {"title": "海外研究｜C-GMT：机器人跟随动作时也能顺着外力让步", "date": "10月16日arXiv新列表｜预印本", "body": "C-GMT冻结预训练通用动作跟踪器，在参考动作前加入小型适配模块，根据本体感知历史修正动作，使机器人被拉住或接触物体时能够顺势让步。作者展示了仿真及Unitree G1上的遥操作、舞蹈、插入和开门实验。", "analysis": "这类方法有望使全身运动更适合接触环境，但不等于安全认证；项目页代码仍标注即将开放，跟踪精度、柔顺性与失稳边界需要进一步验证。", "sources": [{"label": "作者项目页及真机演示", "url": "https://venki1899.github.io/c-gmt/"}]}, {"title": "海外研究｜MoCaP：从人类视频找到移动取物的站位", "date": "10月14日UTC提交，10月15日北京时间｜预印本", "body": "MoCaP从日常人类视频提取物体空间记忆和接近姿态线索，再结合机器人当前观测，调用既有感知、运动与执行工具，寻找底盘可停且机械臂能够触及目标的位置。作者在同一室内环境完成两个移动操作任务的真机验证。", "analysis": "视频中的站位经验可辅助移动操作规划，但验证任务和环境有限，且依赖现成工具链，不能视为跨家庭通用或直接视频模仿。", "sources": [{"label": "arXiv作者摘要", "url": "https://arxiv.org/abs/2610.20998"}]}], "followups": ["复查Digit 5在真实任务负载下的连续工作时间、自动回充占用、温升，以及高频快充后的电池循环老化。", "跟踪NOVA21灵巧手的实际交付时间与价格，并核验TOMO在儿童接触、夹持和有人监督场景中的安全测试。", "核验启元10月15日金融城店是否实际开业，以及门店展示、销售和交付分别达到何种阶段。"], "coverage": "覆盖2026-10-14 18:02至2026-10-16 11:06（UTC+8）。重点公众号公开索引存在滞后与访问缺口；启元金融城店实际开业和交付尚待核验。Astra未获得窗口内新的可核验真机结果，未重复旧回顾。"}, {"date": "2026-10-14", "edition": "6条 · 产品产业5条／研究1条 · 延迟补发", "updated": "18:02", "intro": "本期延迟补发，合并昨天漏发期间的重要进展。爱仕达推出科研本体及制造服务，Physical Intelligence开放模型微调与推理API，机器人开发正增加可直接采购或调用的基础能力。京东的零部件采购平台与ABB的示范学习工具链，则分别尝试降低供应链匹配和现场部署成本；实际效果仍需交付与连续运行数据验证。", "items": [{"title": "国内新品｜爱仕达ASD-S2", "date": "2026-10-13", "body": "爱仕达在上海生态伙伴大会揭牌具身智能创新中心，并发布面向科研及具身算法验证的ASD-S2。公司披露该机型具有31个自由度、单臂负载5公斤，同时提出覆盖核心部件、装配测试和批量交付的OEM、ODM制造服务。", "analysis": "从单一本体延伸至制造服务有助于承接外部方案，但现有资料未核验批量交付能力、连续运行成功率及实际客户采用情况。", "sources": [{"label": "证券时报", "url": "https://www.stcn.com/article/detail/4215143.html"}]}, {"title": "海外产品｜Physical Intelligence API beta", "date": "2026-10-13", "body": "Physical Intelligence开放API测试版，合作伙伴可上传机器人数据，使用其托管算力微调模型，再经托管网关执行推理。官方案例分布于日本、瑞士和美国，展示采集演示、训练测试以及补充失败数据后继续迭代的流程。", "analysis": "托管服务有望降低自建训练基础设施的门槛，但多数案例依赖云端推理，官方也指出连接挑战；选用前仍需核验端到端时延、断网处理、价格与本体适配。", "sources": [{"label": "Physical Intelligence官方", "url": "https://www.pi.website/blog/api-beta"}]}, {"title": "国内供应链｜京东工业采购平台", "date": "2026-10-13", "body": "京东工业在工博会发布机器人零部件一站式采购平台及产业联盟第二期，称平台聚合超过1600家整机原厂、零部件企业、代工厂及代理经销商，可提供标准件、定制部件、一站式BOM物料清单和整机代工服务。", "analysis": "平台可能减少多供应商寻源和物料匹配成本，但1600家属于平台口径，不代表行业份额，也不能直接证明库存深度、质量一致性或交期。", "sources": [{"label": "快科技企业动态", "url": "https://news.mydrivers.com/1/1157/1157160.htm"}]}, {"title": "海外企业在华｜ABB示范学习与AI工具链", "date": "2026-10-12", "body": "ABB在工博会展示GoFa协作机器人通过示范学习获取手冲咖啡的运动轨迹和注水流程，由智能体规划器拆分步骤，EyeMotion完成识别定位；EyeMotion还与AI Robot Trainer连接，形成视觉、训练与执行工具链。", "analysis": "该方案展示了示范学习与流程规划的组合方式，但目前是厂商现场演示，未公开连续试验成功率、人工介入程度或批量部署证据。", "sources": [{"label": "ABB署名发布稿／国际工业自动化网", "url": "https://www.iianews.com/ca/_01-ABC00000000000375989.shtml"}]}, {"title": "海外产业｜Agility上市流程及Digit5订单条件", "date": "2026-10-13", "body": "Agility公告称相关S-4注册声明已于10月13日生效，拟于11月2日进行股东表决，业务合并仍需满足条件。公告重申Digit 5拥有超过3亿美元承诺订单，但订单附带合同里程碑、产品功能或规格条件，早期客户使用目标为2027年初。", "analysis": "资本安排可为生产和交付提供资金，但当前不能写成已经上市，附条件订单也不等于已确认收入或确定交付量。", "sources": [{"label": "Agility Robotics官方公告", "url": "https://www.agilityrobotics.com/content/agility-robotics-and-churchill-capital-corp-xi-s-4-registration-statement-declared-effective-by-sec-in-connection-with-proposed-business-combination"}]}, {"title": "海外研究｜ChunkAct减少机器人重复调用大模型", "date": "2026-10-13 UTC提交，10月14日新论文列表", "body": "ChunkAct把既有操作经验离线整理成可执行步骤串，在线阶段一次调用执行一段，并在各阶段检查结果；失败时返回具体原因，再由大模型决定后续动作。LIBERO-Pro仿真中，同用GPT-5.6-sol高推理设置及相同视觉、动作和记忆模块，成功率由78.8%升至83.8%，平均调用由24.2次降至8.3次。", "analysis": "结果表明分段执行可能降低模型调用成本并改善纠错，但实验仅限仿真，仍依赖动作库、感知和失败检测，不能外推为真机提速或商用效果。", "sources": [{"label": "arXiv预印本原文表1、2", "url": "https://arxiv.org/html/2610.18874v1"}]}], "followups": ["继续核验Physical Intelligence API的端到端网络延迟、断网或弱网处理机制，以及测试版和后续正式服务的定价。", "跟踪ASD-S2是否出现可核验的客户交付、连续运行数据，并核对京东平台所列部件及整机代工服务的实际库存与交期。", "在Agility 11月2日股东表决后复查合并结果；核验启元10月15日门店进展及实际交付，不以开店或展示替代用户收货证据。"], "coverage": "检索窗口2026-10-12 11:04至2026-10-14 18:02（UTC+8），覆盖昨天漏发期间。重点公众号及公开索引存在访问缺口；Astra仿真开发演示的原帖未能核验，本期不据二手描述推导真机进展。"}, {"date": "2026-10-12", "edition": "6条 · 产品产业4条／研究与研发工具2条", "updated": "11:04", "intro": "本期延迟补发，回溯周末重要进展。WR1把双机协作与柔性物整理放进同一演示，接下来要看完整任务能否稳定重复。鹿明与面壁的合作、自变量对关节及触觉企业的投资，将竞争延伸到模型和关键部件协作，但尚不能当作订单兑现。Genesis与Chronos分别处理接触仿真和系统时延，提示验收应覆盖动态工况。", "items": [{"title": "国内｜西湖机器人WR1展示双机协作叠裤与连续家务", "date": "10月9日报道，10月10日新智元跟进｜72小时补充，非当日首发", "body": "机器之心报道的公司演示显示，WR1驱动的人形机器人完成冰箱取物、转身收纳和整理床铺等连续家务，并由两台机器人协作完成取裤、承托、转移、铺展及灵巧手折叠。现有材料能够证明演示涵盖多步任务和双机配合，但未提供可用于评估此次演示的连续试验成功率或人工介入情况，也不能将旧机械臂实验的时间和成功率套用于此次人形双机演示。", "analysis": "增量在于把移动、双机协同和柔性物操作串成较完整流程。判断其可复用性仍需观看未经剪辑的重复试验，并核验失败恢复、协作同步、单次耗时及人工接管。", "sources": [{"label": "机器之心／新浪署名稿", "url": "https://finance.sina.com.cn/roll/2026-10-09/doc-iniurmnm7886282.shtml"}]}, {"title": "国内｜鹿明机器人与面壁智能合作推进数据、模型和场景应用", "date": "10月10日宣布，10月11日报道｜周末重要进展", "body": "鹿明机器人10月10日宣布与面壁智能建立战略合作，合作范围包括数据采集、模型训练和场景应用，计划结合面壁智能的基座大模型与鹿明的机器人本体能力。报道未披露具体订单、部署数量、任务指标、运行时延、成本或客户验收结果。", "analysis": "这项合作覆盖从数据到场景的链条，但当前仍处于合作承诺层面。后续判断重点是双方能否形成明确的动作接口、闭环数据回流和可复现任务结果，以及是否出现客户部署与验收证据。", "sources": [{"label": "观点网", "url": "https://www.guandian.cn/m/show/611587"}]}, {"title": "国内供应链｜自变量同日参与关节模组与柔性触觉企业融资", "date": "10月10日融资官宣，10月11日采访报道｜周末重要进展", "body": "科创板日报报道，无锡巨蟹智能和墨现科技10月10日官宣融资，自变量机器人同时出现在两家企业的投资名单中。前者面向一体化关节模组，后者聚焦柔性触觉传感器，分别对应机器人驱动与感知环节。投资加强了合作联系，但不能由此推导出独家供货关系、已兑现订单或已建成产能。", "analysis": "同日本体企业布局关节与触觉，反映其希望加强关键部件协作和技术连接。实际供应链价值仍取决于批量交付一致性、良率、成本、版本迭代速度，以及这些部件是否进入自变量的正式产品。", "sources": [{"label": "科创板日报记者报道", "url": "https://api3.cls.cn/share/article/2501589?app=stib&os=ios&sv=218"}]}, {"title": "海外供应链｜Misumi高管谈人形量产瓶颈：执行器和精密制造", "date": "10月10日采访｜周末重要进展", "body": "Misumi Americas高管Steve Ricketts在采访中认为，人形机器人扩产时，执行器可能成为主要压力点，其中涉及精密齿轮、轴承和编码器；精密加工与检测能力会影响规模生产的一致性。他建议在设计尚未稳定时保留柔性工艺，待子组件成熟后再使用硬模具，并通过标准化和减少零件降低成本。", "analysis": "这是供应商观点，并非全行业产能普查、缺货统计或采购报价。其可操作价值在于提醒团队把批次良率、交期和版本管理纳入量产评估，避免在设计频繁变化阶段过早固化工装。", "sources": [{"label": "Robotics & Automation News原始访谈", "url": "https://roboticsandautomationnews.com/2026/10/10/interview-humanoid-robots-are-advancing-fast-manufacturing-them-at-scale-is-the-next-challenge/105812/"}]}, {"title": "研发工具｜Genesis v1.4.4更新GPU仿真与接触稳定性", "date": "10月11日UTC发布，10月12日北京时间", "body": "Genesis官方发布v1.4.4，更新图形处理器（GPU）刚体仿真速度及扰动条件下多接触的稳健性，修复凸体接触深度、法向和位置问题以及GPU非确定性，并减少异构实体内存占用与重复编译。版本说明没有披露统一倍速或真机任务提升数据。", "analysis": "更新主要影响机器人训练和仿真工程，不能据此推断真机成功率提高。升级后应在同一任务上回归吞吐量、结果可重复性和接触轨迹，尤其检查旧训练数据与新版本的兼容性。", "sources": [{"label": "Genesis官方版本说明", "url": "https://github.com/Genesis-Embodied-AI/genesis-world/releases/tag/v1.4.4"}]}, {"title": "海外研究｜Chronos Policy：让机器人知道看到和行动之间隔了多久", "date": "10月9日UTC提交，10月12日arXiv新列表｜预印本", "body": "斯坦福团队为观测和执行动作附加物理时间信息，并在训练中随机改变观测采样与动作开始时刻，以适应传感器异步和推理延迟。在把杯子放到移动碟子的真机任务中，叠加感知与推理时延扰动后，Chronos完成5/10次完整成功、1次部分成功；作为对照的扩散策略为3/10次完整成功、无部分成功。", "analysis": "结果表明显式建模时间可能改善动态操作，但样本仅10次，属于预印本和小规模真机实验，不能称为消除延迟或产线验证。更直接的应用是把时延、抖动和丢帧纳入机器人验收，而非只测静态任务。", "sources": [{"label": "论文及真机结果表7", "url": "https://arxiv.org/html/2610.13929v1"}]}], "followups": ["WR1公布连续试验和人工介入信息时复查；面壁智能与鹿明机器人出现首个联合部署及验收结果后更新。", "跟踪关节模组与柔性触觉企业的交付、良率和报价，继续区分投资关系与实际供货。", "湖北项目公示截至10月12日，结束后复查正式中标结果；启元10月15日门店开业及交付量待核验。"], "coverage": "检索窗口2026-10-10 14:16至2026-10-12 11:04（UTC+8），覆盖周末，并补充72小时内未报内容。具身智能之心、新智元、量子位已分别检索，公众号与公开索引存在缺口。Astra未核验到窗口内新增真机结果，未重复旧演示。"}, {"date": "2026-10-10", "edition": "7条 · 产业与竞品5条／研究2条", "updated": "14:16", "intro": "调休工作日补发。今日观察：①Ultra的按月服务与加速进化的日本代理，显示商业竞争正延伸到交付和运营支持。②零组件出货与研发采购提供更具体的产业信号，但须分清部件、整机、候选报价和正式合同。③两篇研究分别处理执行风险与训练效率，真机验证边界仍比单一高分更有判断价值。", "items": [{"title": "海外｜Ultra获5000万美元A轮，继续扩张仓库机器人服务", "date": "10月9日披露", "body": "Ultra官网宣布5000万美元A轮融资。Humanoids Daily报道，公司与Physical Intelligence深化合作，采用前期集成费加月度软硬件支持费的服务模式；OP1面向包装、分拣和配套作业，公司称累计包装超过50万单。", "analysis": "这类固定工位双臂方案把竞争点落在单均成本和持续产出。累计订单为公司披露，未给出统一接管率与服务毛利；融资额也不能当作设备订单。", "sources": [{"label": "Ultra官网", "url": "https://ultra.tech/"}, {"label": "Humanoids Daily", "url": "https://www.humanoidsdaily.com/news/ultra-50-million-series-a-warehouse-robots-physical-intelligence"}]}, {"title": "国内出海｜加速进化K1、T2进入ELSA日本销售渠道", "date": "10月8日官方公告｜72小时补充", "body": "ELSA Japan宣布与Booster Robotics签订日本销售代理协议，提供研究教育向K1及旗舰T2，计划11月出货，售价需询价。官方列明K1约95厘米、19.5公斤，T2约140厘米、42公斤；T2可选Jetson Thor计算配置。", "analysis": "增量是日本本地渠道和交货计划，不是两款机器人的首次发布。对海外客户，采购、调试及售后可获得性同样影响选型；仍需核验各版本到货和支持范围。", "sources": [{"label": "ELSA Japan官方公告", "url": "https://www.elsa-jp.co.jp/newsrelease/booster-robotics-partnership/"}]}, {"title": "国内｜比亚迪人形机器人外观专利曝光", "date": "10月9日报道", "body": "CnEVPost报道，国家知识产权局10月9日公开比亚迪具身智能机器人的外观专利，配图呈现双臂双足与关节手指。报道同时指出，截至当日公司尚未正式发布该产品；本期尚未取得可直接访问的专利登记原页。", "analysis": "这是汽车企业进入机器人市场的新公开线索，但外观不提供负载、续航或量产证据。竞争判断应等待正式配置、定价与首批应用场景，而不是从专利图片推算产品成熟度。", "sources": [{"label": "CnEVPost报道及专利配图", "url": "https://cnevpost.com/2026/10/09/byd-humanoid-robot-design-emerges/"}]}, {"title": "国内｜长盈精密称前八个月交付超110万件机器人零组件", "date": "10月8日披露｜72小时补充", "body": "格隆汇转述公司互动平台答复：2026年1—8月交付超过110万件人形机器人精密零组件，与国内外多家头部品牌合作，并根据客户需求扩产；公司称三、四季度订单相比上半年增速更快。", "analysis": "零部件出货给出了比概念合作更具体的供应链信号，但“件”不能换算为机器人台数。客户结构、单机价值量与机器人业务收入未在快讯披露，四季度说法仍包含前瞻判断。", "sources": [{"label": "格隆汇转述公司答复", "url": "https://www.gelonghui.com/live/2701879"}]}, {"title": "国内｜湖北具身大模型研发项目公示评标结果", "date": "10月9日官方公示", "body": "湖北人形机器人创新中心委托的研发项目公布评标结果，北京大学武汉人工智能研究院排名第一，投标报价1985万元；公示期为10月9日至12日。另两家候选报价分别为2000万元和1800万元。", "analysis": "这是研发采购推进的证据，尚不能计作最终合同、付款或交付。后续需看正式中标及验收条款，才能判断购买的是哪些能力、是否形成可复用的平台。", "sources": [{"label": "湖北省成套招标公示", "url": "https://www.hubeibidding.com/view/53024.html"}]}, {"title": "算法研究｜CSF：同一个动作，换了对象就要重新判断风险", "date": "10月8日UTC提交，10月9日北京时间｜预印本", "body": "CSF给动作生成器增加按场景触发的过滤层：对物体允许的挥击，场景中出现人时应改成安全动作。四个生成器、2688段对照动作测试中，作者定义的危险事件率最多相对下降90%；另在宇树G1展示了人在执行途中进入视野时的动作中断。", "analysis": "它补上了只检查文字指令的盲区；90%是离线动作指标，不是真机事故率。人的识别、规则覆盖及长时间交互仍需验证，不能据此认定已满足商业安全要求。", "sources": [{"label": "论文原文与试验设置", "url": "https://arxiv.org/html/2610.12467v1"}]}, {"title": "算法研究｜SGS：让机器人多练“差一点就能成功”的任务", "date": "10月8日UTC提交，10月9日北京时间｜论文公开版", "body": "华盛顿大学团队按当前成功率调整训练题目，减少反复练习已掌握或暂时太难的情况。仿真训练后迁移到UR5e：齿轮插入成功47/50次，螺母螺栓装配为18/48次；后者在仿真中约90%，真机只有37.5%。", "analysis": "方法提供了提升训练资源利用率的思路，也暴露不同装配任务的迁移差距。选型应同时看首次成功率、重试次数和单位时间产出，不能只拿仿真最高分估算产线节拍。", "sources": [{"label": "论文及真机结果表2", "url": "https://arxiv.org/html/2610.12465v1"}]}], "followups": ["10月12日后复查湖北项目最终中标；11月核验K1/T2日本实际出货及服务范围。", "等待比亚迪正式发布与长盈后续财报，再更新产品配置、整机对应价值量与收入判断。", "今后按中国大陆实际工作日11:00发送，调休补班照常；10月11日休息，下一期回溯本期截止后的周末重要消息。"], "coverage": "截止2026-10-10 14:16（UTC+8）。以10月9日11:06后新增披露为主，补充72小时内未报内容。具身智能之心、新智元、量子位已分别检索；公开索引和公众号访问存在缺口。Astra仿真开发报道与昨日重复，本期不重复收录。"}, {"date": "2026-10-09", "edition": "8条 · 新品／落地／供应链／论文", "updated": "11:06", "intro": "延迟发送：本期核验与编写未能在11:00前完成。今日判断：①正行与优必选把目标落到补货、巡检和厂内物流，验收应跟着具体任务走。②CRIS-0和DreamTrue都在处理“看起来完成、实际失败”的问题，研发应单列结果核验与失败恢复。③Astra的新进展是辅助构建和调试仿真，不能把开发工具能力与真机策略成绩混为一谈。", "items": [{"title": "国内｜新品：正行创新发布H1、C1与零售运营方案", "date": "10月8日APRCE发布", "body": "量子位刊载发布信息：正行创新推出双足人形H1、窄体轮臂C1及统一管理平台M1，面向补货、搬运、盘点和巡检，平台支持人工接管。商业服务计划2027年启动，可采购或订阅；现阶段将与连锁零售伙伴开展测试。", "analysis": "“24/7”是目标场景，不是已证明全年无故障；99%自主完成的宣传缺少公开测试分母，需用店内任务节拍和接管率验收。", "sources": [{"label": "量子位发布报道", "url": "https://www.qbitai.com/2026/10/502035.html"}]}, {"title": "国内｜工厂落地：优必选与一汽大众推进物流场景", "date": "10月8日披露｜72小时补充", "body": "第一财经转述优必选消息称，双方近日达成战略合作，将共同开发、测试具身机器人物流应用，并构建示范场景。增量是物流任务开发与测试安排；公开快讯未给出采购数量、金额、部署车型或稳定运行成绩。", "analysis": "应跟踪首个可验收工位、节拍和接管记录；合作协议不能计作已交付订单，也不宜当作双方首次接触。", "sources": [{"label": "第一财经", "url": "https://www.yicai.com/brief/103385313.html"}]}, {"title": "海外｜模型系统：Aether发布带阶段核验的CRIS-0", "date": "10月8日官方技术报告", "body": "CRIS-0把任务拆成可核验阶段，结合因果世界模型、学习策略、规则函数与导航工具；执行后检查结果，失败可重试、退回阶段或修正工具。官方展示真实机器人家务任务，但没有在页面给出统一完整任务成功率和独立测试。", "analysis": "相比只看动作是否执行，阶段结果核验更适合长流程；仍需统计漏检、误判与恢复成本，不能把演示当作家庭安全认证。", "sources": [{"label": "Aether官方技术报告", "url": "https://aetherlabs.ai/articles/real-world-autonomous-robotic-system-with-causality-driven-agent-and-world-model"}]}, {"title": "海外｜Astra×机器人：NVIDIA展示代理辅助仿真开发", "date": "10月8日官方发布", "body": "NVIDIA介绍开发者用GPT-6 Astra连接Omniverse物理、渲染和场景库，搭建仓库人形仿真、设计拆装工具并迭代控制器。G1跨栏示例在100次仿真试验中成功64次；全过程由开发者提出需求、检查结果和引导修改。", "analysis": "这里Astra主要承担研发工具与控制器开发，成绩属于仿真；下一步应对照人工开发耗时、物理误差和真机迁移，而非宣称机器人已自主学会跨栏。", "sources": [{"label": "NVIDIA官方案例", "url": "https://blogs.nvidia.com/blog/developers-simulation-frontier-ai-agents/"}]}, {"title": "国内｜供应链：中科摩通披露机器人部件装配测试方案", "date": "10月8日官网披露；峰会具体日期未列", "body": "中科摩通称已研发面向减速器、丝杠、灵巧手、电机和关节模组的制造设备，将汽车领域压装、拧紧、焊接及测试工艺迁移至机器人部件，覆盖单工序至整线和出厂终测。公告展示方案，未披露新增客户订单与实测良率。", "analysis": "量产判断应把部件设计与装配一致性分开；需要验收节拍、良率、换型成本，不能从展示直接推算人形产能。", "sources": [{"label": "中科摩通官方公告", "url": "https://casmt.com/newsinfo/394.html"}]}, {"title": "国内｜融资与数据：厘清智能完成两轮数亿元融资", "date": "10月8日宣布", "body": "投资界报道，厘清智能完成天使轮及天使+轮数亿元融资，蚂蚁集团连续投资并领投天使+轮。资金拟用于数据、模型、物理仿真、评测和跨本体部署；公司已推出T1数采手套及Ego采集设备，具体各轮金额未披露。", "analysis": "资金流向从本体扩展到数据与适配服务；平台价值仍要由付费客户、数据质量及跨设备复用效果证明，融资不等于技术验收。", "sources": [{"label": "投资界原始报道", "url": "https://news.pedaily.cn/202610/569895.shtml"}]}, {"title": "海外合作｜新论文：Dex-One2Many从单视频学习灵巧操作", "date": "10月8日提交预印本，10月9日arXiv列表收录", "body": "方法把人类演示转为分阶段场景关系图，用于仿真强化学习的初始状态与奖励，再零样本部署到UR3及20自由度Wuji手。五类任务中，每方法每任务测10次已见、20次未见配置；作者报告未见配置平均成功率75%。", "analysis": "单视频不等于免训练：仍需大规模仿真及物体位姿估计。接触误差、几何偏差会影响真机，有限任务结果不能外推任意工具。", "sources": [{"label": "论文与试验口径", "url": "https://arxiv.org/html/2610.12470v1"}, {"label": "作者项目页", "url": "https://dex-one2many.github.io/"}]}, {"title": "国内｜新论文：DreamTrue减少世界模型对失败的误判", "date": "10月8日提交预印本，10月9日arXiv列表收录", "body": "中科院自动化所与高德团队用几何校准、反事实动作及视频奖励后训练改进预测。三类双臂仿真任务、四种VLA、240条动作轨迹构成24组条件；预测成功率的平均绝对误差从12.92降至7.08个百分点。", "analysis": "价值在于让失败抓取也被预测为失败；这是世界模型评估准确度，不是机器人成功率提升。未见场景和长时接触仍需外部验证。", "sources": [{"label": "论文原文", "url": "https://arxiv.org/html/2610.12468v1"}, {"label": "作者仓库入口（未实跑）", "url": "https://github.com/brave-eai/DreamTrue"}]}], "followups": ["零售与物流：出现首店／首工位报告时，复查任务分母、连续运行、接管率与成本；正行2027商业化安排持续跟踪。", "算法：对同一失败任务检查核验误报、恢复耗时和总成本；DreamTrue先验证排名与失败预测，再用于策略选型。", "周末停发：10月10日虽调休补班也不推送；下一工作日报回溯自本期截止时间，合并周末大新闻。"], "coverage": "截止2026-10-09 11:06（UTC+8），以昨日成功日报截止10月8日11:47后的新增信息为主，必要补充72小时内未报内容。逐一检索具身智能之心、新智元、量子位；量子位新品原文可读，具身智能之心公开索引滞后，微信公众号覆盖仍有缺口。"}, {"date": "2026-10-08", "edition": "9条 · 节后汇总 · 延迟补发", "updated": "11:47", "intro": "延迟补发｜节后汇总。①启元从发售进入首批交付，爱宝也披露活动数据，商业判断应转向履约量与接管率。②Dyna和德塔强调跨动作连续执行，选型需测试交接、平衡与失败恢复。③两篇Astra新论文提示，接口和技能库会显著影响表现，应固定模型、任务与预算再比较；上述为本期研究判断。", "items": [{"title": "国内｜交付：启元首批产品到用户手中", "date": "10月1日｜假期重要进展", "body": "上观号授权稿经新浪转载披露，启元授权体验店在上海、深圳、杭州同步开启首批交付，彭志辉到场向用户颁发交付证书。这补上了此前“10月1日起交付”的待核查结果；报道未披露交付台数、订单履约比例或长期使用数据。", "analysis": "首批交付证据比发售预告更进一步，下一步应看持续履约与用户故障反馈，不能从仪式推算销量。", "sources": [{"label": "上观号授权稿／新浪", "url": "https://finance.sina.com.cn/jjxw/2026-10-01/doc-inittvfv5083565.shtml"}]}, {"title": "国内｜模型：德塔Delta-0连接全身控制与操作", "date": "9月下旬发布；9月29日新智元报道｜停发期间进展", "body": "德塔官方报告将69自由度全身控制器与世界—动作模型结合，展示铺床、开洗碗机等任务。长流程接受阶段指令；公司还称用Astra辅助重建仿真资产。镜像厨房内部试验中，加入人工纠正与强化学习后，洗碗机任务从4/20成功提高至13/20。", "analysis": "重点是控制、数据与纠错接口协同；这是公司内部试验，阶段指令与人工训练纠正不能省略为“完全自主通用家政”。", "sources": [{"label": "德塔技术报告", "url": "https://deltai.com/en/blog/delta-0"}, {"label": "新智元／新浪", "url": "https://finance.sina.com.cn/stock/t/2026-09-29/doc-initnfqc7871973.shtml"}]}, {"title": "海外｜新品：Dyna用Taku串起一小时洗衣流程", "date": "9月29日｜停发期间进展", "body": "Dyna推出轮式半人形Taku和Dyna-2.1，官方提供称为自主、未剪辑的一小时洗衣流程演示，覆盖洗涤、烘干、折叠及上架。Taku以双7自由度手臂、可折叠下身和四个转向轮跨工位作业，系统结合操作策略与流程决策。", "analysis": "验收应从单次折叠转向跨工位交接和失败恢复；公司演示尚不能代表客户现场跨班次可靠性。", "sources": [{"label": "Dyna官方技术报告", "url": "https://www.dyna.co/dyna-2.1"}]}, {"title": "海外发布｜供应链：Sharpa同时推出本体、灵巧手与采集手套", "date": "9月28日美东公告，UTC+8为9月29日｜停发期间进展", "body": "Sharpa在IROS公布D01机器人、W02灵巧手和AE01数据手套。公司披露W02具21个主动自由度、重量低于750克，并将触觉覆盖扩展到手指和手掌；AE01采用22自由度采集结构，配合反馈支持操作数据采集。", "analysis": "一体配套可能降低本体与采集系统适配工作量；具体报价、批量供货和独立耐久测试仍需核验。", "sources": [{"label": "Sharpa公司公告／美通社", "url": "https://www.prnewswire.com/news-releases/sharpa-unveils-three-flagship-products-d01-robot-w02-dexterous-hand-and-ae01-data-glove-at-iros-2026-302892129.html"}]}, {"title": "海外｜灵巧操作：Atlas新手增至13自由度", "date": "10月1日报道｜假期重要进展", "body": "Boston Dynamics官方介绍Atlas新一代四指手：从7提升至13自由度，采用关节直接驱动和触觉感知，面向手内调整、工具操作及高保真仿真训练。公司解释，少一根手指可减少执行器、体积和潜在故障点；展示视频包含遥操作片段。", "analysis": "可比较自由度与可维护性的取舍，不能把演示动作全部算作自主完成，也不能只按指头数量评优劣。", "sources": [{"label": "Boston Dynamics技术说明", "url": "https://bostondynamics.com/blog/robot-hands-for-modern-ai-and-real-work"}]}, {"title": "国内／国际合作｜论文：PyRUA-Lean优化Astra机器人调用", "date": "10月1日提交预印本｜假期重要进展", "body": "作者在700个仿真任务实例中，以相同Astra规划器、动作能力和调用预算比较代码执行与逐项工具调用：成功率由63.1%升至71.7%。双方都成功的实例上，输入token减少65%；方法把条件检查、重试和选择性观察合并进代码。", "analysis": "增益来自接口组织，不能称为新模型战胜VLA；节省口径只限共同成功样本，也不等于真机耗时降低65%。", "sources": [{"label": "论文原文", "url": "https://arxiv.org/html/2610.01939v1"}, {"label": "作者代码（已核验入口，未实跑）", "url": "https://github.com/DAGroup-PKU/PyRUA-Lean"}]}, {"title": "学术｜论文：Skill2Real将仿真技能迁移到真机", "date": "10月2日提交预印本｜假期重要进展", "body": "Skill2Real在仿真中学习并冻结分层可执行技能，再经统一接口用于真机。固定Astra和接口，UR5e四类任务、每方法每类20次试验中，平均完成率从无技能库的27.50%升至78.75%；抽屉任务仍仅50%。", "analysis": "这支持单独评估技能库的贡献；四类桌面任务和有限样本不代表人形全身作业能力，本次未核验可运行代码。", "sources": [{"label": "论文与真机实验表", "url": "https://arxiv.org/html/2610.02788v1"}]}, {"title": "海外｜安全供应链：Agility与FORT扩展Digit安全接口", "date": "10月1日｜假期重要进展", "body": "双方签署合作备忘录，计划深化Digit 5的三部分安全架构：安全手持终端、机器人端通信，以及连接外部安全系统的接口。官方说明手持终端用于设置、维护或异常时的独立人工覆盖，补充机器人机载安全能力。", "analysis": "车间接入和急停链路是部署成本的一部分；备忘录不等于完成认证，也不是新增客户订单。", "sources": [{"label": "Agility官方公告", "url": "https://www.agilityrobotics.com/content/agility-and-fort-robotics-announce-strategic-partnership-to-advance-humanoid-robot-safety"}]}, {"title": "国内｜落地追踪：爱宝门店活动披露首日数据", "date": "9月28日活动、9月29日报道｜上期预告后续", "body": "财联社刊载的活动稿披露，9月28日三店直播采集到10小时运行展示、4299次人机交互，并说明机器人轮换上岗。此次有了实际活动结果，但接管次数、停机、独立用户数和转化分母未披露，不能视为单机连续自主运行十小时。", "analysis": "下一轮应索取分机时长和人工介入记录，才能判断热闹的互动是否能复制为稳定服务。", "sources": [{"label": "财联社刊载活动稿", "url": "https://m.cls.cn/detail/2495303"}]}], "followups": ["启元：继续核验交付数量、用户持续使用反馈及10月15日广州金融城店计划；有实际开业或履约数据时更新。", "算法：复现PyRUA-Lean和Skill2Real时固定任务、模型与预算，同时记录总尝试成本、耗时和失败；两篇成绩不能直接横比。", "落地：跟踪Taku客户现场跨班次表现、爱宝分机接管率，以及新灵巧手供货与耐久测试。"], "coverage": "回溯2026-09-28 11:15至2026-10-08 11:47（UTC+8），包含国庆假期及此前未成功发送区间。逐一检索具身智能之心、新智元、量子位并扩展行业媒体；具身智能之心公开转载索引滞后，微信公众号覆盖不完整，不承诺无遗漏。"}, {"date": "2026-09-28", "edition": "5条 · 延迟补发 · 物理评测、运控开源与落地", "updated": "11:15", "intro": "延迟补发：本机任务恢复后执行，本期未能在11:00准点发送。今日判断：①美梦空间将物理参数扰动列为模型评测对象，提示选型应增加质量、摩擦变化测试，不能只看视觉泛化分数。②Asimov公开运控训练框架，研发团队可以检查PPO与AMP配置；但代码可用不等于真机可靠性已验证。③爱仕达预告披露门店运行数据，HD现代则计划在自身装配线训练，商业验证应转向连续运行、人工接管和任务节拍。以上为基于本期证据的研究判断。", "items": [{"title": "国内｜模型发布／评测：美梦空间推出Physical-WAM与物理扰动基准", "date": "9月26日数贸会发布；相关基准预印本9月22日提交。", "body": "美梦空间供稿、量子位转载称，Physical-WAM通过物理表征连接感知、预测与动作。配套RoboTwin-Phys论文在双臂仿真中引入13类参数变化，并提供逾5000条带物理参数的专家示范；受测模型在物理扰动下明显退化。论文属预印本，不能把基准结果当作新模型已获真机验证。", "analysis": "新增价值是把摩擦、质量等变化纳入验收；论文对照部分引用既有公开成绩，仍需统一环境复现。本次未核验可运行的官方代码入口。", "sources": [{"label": "美梦空间供稿／量子位", "url": "https://www.qbitai.com/2026/09/498478.html"}, {"label": "基准论文与实验口径", "url": "https://arxiv.org/html/2609.26292v1"}]}, {"title": "国内｜商业落地预告：爱仕达计划连续三天公开爱宝门店作业", "date": "9月27日晚报道；活动计划9月28—30日。", "body": "财联社报道的活动安排显示，爱宝拟在温岭炊具旗舰店上岗，并联动上海、无锡门店，执行迎宾、导购、带路和发券。公司计划公布运行时长、接待人数、互动频次与扫码转化次数。本期核验的是活动计划，尚未取得当天完整运行成绩及人工接管记录。", "analysis": "比单次舞台演示更可检验，但接待量不等于自主完成率；应把机器人独立作业、人工协助及商业转化分别统计。", "sources": [{"label": "财联社／东方财富", "url": "https://finance.eastmoney.com/a/202609273884511065.html"}]}, {"title": "海外｜运控开源：Asimov开放PPO与AMP训练框架", "date": "9月25日发布消息，9月26日报道；72小时补充。", "body": "Menlo Research的Asimov 1官方仓库已提供基于Isaac Lab的运动策略训练与评估代码，包含普通PPO基线和推荐的AMP配置，支持单卡、多卡训练及策略导出。仓库明确列出环境与显卡要求；已核验训练入口，未实跑，也未核验可直接下载的预训练权重。", "analysis": "适合作为比较奖励设计、动作先验与sim-to-real配置的工程样本；真机迁移仍需核对本体参数、执行器和实测稳定性。", "sources": [{"label": "官方训练代码", "url": "https://github.com/menloresearch/isaac_asimov/"}, {"label": "发布日期与开放范围报道", "url": "https://www.humanoidsdaily.com/news/asimov-open-source-locomotion-policy-training"}]}, {"title": "海外｜制造业：HD现代拟把人形机器人AI复用到既有产品线", "date": "9月27日CTO书面采访。", "body": "HD Hyundai Robotics CTO在首尔经济日报采访中表示，人形项目处于原型、操作任务训练与验证阶段，计划进入自身控制器装配线采集数据。感知、精细操作、力触觉控制和任务规划能力拟复用到工业及协作机器人。采访未给出人形量产上市日期或稳定作业成绩。", "analysis": "这提供了以现有工业客户与产线承接具身技术的路径；目前是研发路线，不能把协作机器人销售目标算成人形机器人订单。", "sources": [{"label": "首尔经济日报原始采访（英文译文）", "url": "https://en.sedaily.com/finance/2026/09/27/hd-hyundai-robotics-to-extend-humanoid-ai-tech-to"}]}, {"title": "海外｜供应链：Seyond在IROS展示面向机器人近场感知的激光雷达", "date": "9月25日官方公告；72小时补充，非首次发布产品。", "body": "Seyond宣布在IROS展示机器人传感方案，覆盖人形、物流及配送平台。官方列出Hummingbird D1R的紧凑设计、140°×100°视场和近距检测，并称继续开发更小、更轻、更低功耗方案。公告没有披露人形客户订单、机器人领域出货量或新的产品价格。", "analysis": "选型可关注安装空间与近场盲区，但全业务累计交付百万传感器不等于人形订单；供货与成本判断仍需具体客户和报价。", "sources": [{"label": "Seyond官方公告", "url": "https://seyond.com/from-warehouses-to-sidewalks-seyond-scales-lidar-for-the-next-generation-of-robotics/"}]}], "followups": ["爱宝：9月28日晚至30日公布成绩后复查运行时长、停机和接管次数；只有完整分母才能判断是否具备复制条件。", "物理评测与运控：待RoboTwin-Phys可运行代码、独立复现或Asimov真机连续运行结果出现，再比较同任务成功率、耗时和失败类型。", "用户点名主线：启元继续核实10月1日起真实交付，9月27日门店报道另提10月15日广州金融城店试营业；Astra继续等待可核验的原始实速视频、同预算评测与成本数据。"], "coverage": "逐一检索具身智能之心、新智元、量子位；量子位本次原文可读，具身智能之心转载索引滞后。Astra实速演示的作者原帖访问受限，未将转载结论作为已核实新闻；9月24日K1预印本已核验但超出72小时窗口，留作专题跟踪。本期只选5条，不用旧闻凑数。"}, {"date": "2026-09-22", "edition": "6条 · 新品、落地与模型评测", "updated": "10:37", "intro": "今日判断：①宇树公开灵巧手售价，Atlas启用工厂训练中心，硬件竞争正接受成本与现场可靠性的检验。②RPent提供可复用的“大模型规划＋专用策略执行”框架，但加速有成功率代价；评估时应同时看时延与失败恢复。③Light-O1的人类动作预训练与RoboHarm的拒绝测试提示：动作能力、跨本体迁移和安全必须分别测量。以上为基于本期证据的研究判断。", "items": [{"title": "国内｜新品／供应链：宇树发布Dex5-S，单手3.99万元起", "date": "9月21日晚发布。", "body": "据证券时报、中国基金报报道，宇树发布真手1:1尺寸的Dex5-S，单手22自由度，售价3.99万元起。发布演示涵盖拿勺、剪纸和动态抓握；中国基金报转述单手最大负载2公斤、持续负载1公斤。上述为发布参数与演示，尚非独立耐久性或成功率测试。", "analysis": "这为灵巧手选型提供新的公开价格参照；需进一步核对触觉版本、接口、寿命和交期，不能仅以自由度判断整机操作能力。", "sources": [{"label": "证券时报／东方财富", "url": "https://finance.eastmoney.com/a/202609213880222695.html"}, {"label": "中国基金报／新浪", "url": "https://finance.sina.com.cn/jjxw/2026-09-21/doc-inisqzxv7591986.shtml"}]}, {"title": "海外｜工业落地：Atlas工厂训练中心在现代美国工厂启用", "date": "9月21日官方公告。", "body": "Boston Dynamics宣布RMAC首期已在现代美国工厂园区投入运行，Atlas正在练习汽车零部件物流、排序与装配前摆放。公司计划2027年迁入约十倍规模设施，2030年扩展至部件装配；本次公告未给出现场节拍、错误率或已部署机器人数量。", "analysis": "增量是生产现场训练基础设施落地。未来部署量和规划产能仍是目标，不应当作当前订单兑现或稳定量产。", "sources": [{"label": "Boston Dynamics官方", "url": "https://bostondynamics.com/news/boston-dynamics-opens-robotics-metaplant-application-center-to-train-humanoid-robots-for-manufacturing-tasks/"}]}, {"title": "国内｜商业试运营：大晓机器人进入中国石油便利店履约流程", "date": "9月21日报道；合作及试运营发生于近日。", "body": "中国证券报向大晓机器人获悉，其与中国石油上海销售合作，首店振兴店昆仑好客已试运营。公司披露，美团订单经石油数智平台进入作业系统，机器人在75厘米通道、2米货架条件下拣选、搬运、打包并更新订单状态；尚未披露连续运营效率、人工接管率与项目金额。", "analysis": "从展示抓取转向真实订单闭环是有价值的验证；能否扩店，应以峰值订单履约、故障恢复和运营成本衡量。", "sources": [{"label": "中国证券报采访", "url": "https://www.cs.com.cn/ssgs/01/2026/09/21/detail_2026092110040700.html"}]}, {"title": "国内｜算法／开源：RPent连接Astra规划与VLA执行", "date": "9月21日正式发布；量子位线索，已核验官方与代码。", "body": "清华、无问芯穹、正行创新开源RPent，将通用模型规划、专用策略、工具和记忆连接起来。官方报告Astra配置在LIBERO-Pro仿真达92.63%；另一组LIBERO Object的200次评测中，任务卡模式将平均执行时间从283.6秒降至40.9秒，成功率下降3.5个百分点。", "analysis": "可测试重复任务能否通过经验复用减少推理开销；这两组指标不可拼成同一实验，也不是“真机92.6%成功率”或全面替代VLA。", "sources": [{"label": "官方发布与实验口径", "url": "https://www.infinigence-ai.com/news-updates/239.html"}, {"label": "官方代码", "url": "https://github.com/RLinf/RPent"}]}, {"title": "国内｜技术报告／模型：Light-O1以人类动作预训练扩展全身智能", "date": "9月21日发布；公司技术报告，非已核验的同行评审论文。", "body": "亮源新创发布Light-O1及Preview。官方报告完整模型在RoboCasa GR-1的24项仿真桌面任务上，按每项50次评估取得79.3%宏平均成功率。开源Preview接收文字并输出统一人体动作表示；G1示例通过GEAR-SONIC控制器执行，仓库提供的是MuJoCo仿真示例。", "analysis": "值得验证人类动作先验对运控与跨本体适配的价值；开源Preview不等于完整视觉移动操作系统，仿真成绩和真机展示须分开看。", "sources": [{"label": "官方技术报告", "url": "https://www.lightorigins.cn/en/blog/light-o1"}, {"label": "代码与开放范围", "url": "https://github.com/lightorigins/Light-O1"}]}, {"title": "海外｜Astra安全专题：RoboHarm要求把“会做”和“该做”分开评测", "date": "9月18日原始评测；9月21日新智元、量子位集中报道，本期专题补充。", "body": "Robocurve在同一双臂YAM平台测试3种策略、5类危险指令，每格20次，共300次。原文记录Astra因安全原因拒绝2/100次，Fable为20/100；MolmoAct2没有原生拒绝机制，低完成率不能说明更安全。研究限于固定措辞和五个场景，代码并非冻结的完整结果数据集。", "analysis": "接入真实设备时应单列拒绝、权限边界和人工接管测试；不把单台实验推广成所有场景结论，也不照搬媒体混用的完成率分母。", "sources": [{"label": "原始评测与限制", "url": "https://robocurve.org/roboharm/"}, {"label": "开源工具及复现边界", "url": "https://github.com/robocurve/roboharm"}]}], "followups": ["Dex5-S：获得正式规格、交期或第三方寿命测试时复查；把持续负载、触觉配置与热稳定性列为选型条件。", "Atlas与便利店试点：披露连续运营小时、任务节拍、人工接管率或扩店订单后更新；启元仍按10月1日起实际交付跟踪。", "RPent与Light-O1：出现独立复现时检查同任务、同预算的成功率／耗时／成本；先区分模型、控制器和公开材料范围。"], "coverage": "已逐项检索具身智能之心、新智元、量子位；部分公众号原文及量子位页面访问失败，具身智能之心公开转载索引明显滞后，已通过署名报道和一手源补查，不能视为完整覆盖。"}, {"date": "2026-09-21", "edition": "修订版 · 8 条", "updated": "14:06", "intro": "启元新品开始接受价格、开发生态与实际交付的检验。通用模型进入机器人，应评估与专用策略和控制器的分工；供应链判断仍需落到真实订单和部署效果。本期补入近期Astra研究，明确其原始时间与验证边界。", "items": [{"title": "国内｜新品首条补报：启元 Q1 与 T1 正式发售", "date": "9 月 20 日发布；本次补入首条。", "body": "启元发布 Q1、T1 两款个人机器人，基础版均为 19999 元，Q1 探索版 26999 元，T1 Pro 29999 元。新智元报道：探索版开放 SDK／HDK，T1 Pro 增加 Orin Nano 及回充等功能；公司披露每 2.5 分钟下线一台，并公布运控、跟随、交互模型与技能生态。报道正文写明 10 月 1 日起按订单顺序发货，不能将“发售即发货”标题理解为当前全部现货交付。", "analysis": "从价格、开发接口和消费场景判断，这是昨天应优先收录的新品事件；下一步看真实交付、安全与留存，产线节拍不能换算成销量。", "sources": [{"label": "新智元／新浪分发", "url": "https://finance.sina.com.cn/wm/2026-09-20/doc-inisnssr1349676.shtml"}, {"label": "证券时报采访", "url": "https://egs.stcn.com/news/detail/2343387.html"}]}, {"title": "国内｜产业与融资：智身科技完成数亿元 B 轮融资", "date": "9 月 20 日披露。", "body": "据第一财经转引公司消息，本轮由阿联酋 Stone Venture 领投，洪山资本及多家产业投资方参与，资金用于本体、具身大小脑和任务作业能力。新京报明确其披露的累计量产超过 1.5 万台是行业级四足机器人口径，尚未披露人形机器人量产情况，不能将这个数字当作人形机器人销量。", "analysis": "值得跟踪能源、安防等场景中的付费部署与复购，以及成熟四足平台能力向人形平台迁移的实际进度。", "sources": [{"label": "第一财经", "url": "https://www.yicai.com/brief/103371070.html"}, {"label": "新京报", "url": "https://www.bjnews.com.cn/detail/1789881689129881.html"}]}, {"title": "国内｜上游供应链：千觉机器人连续完成两轮数亿元战略融资", "date": "9 月 19 日报道。", "body": "科创板日报报道称，千觉近期连续完成两轮数亿元战略融资，资金投向高精度视触觉传感器迭代与规模交付，并建设真实交互数据采集、触觉仿真和数据集，研发触觉具身模型及世界模型。报道未给出两轮各自的精确金额，不作拆分估算。", "analysis": "触觉供应商的竞争正在延伸到数据与模型。选型时应把一致性、耐久性、标定成本和接触任务成功率一起考察。", "sources": [{"label": "科创板日报／东方财富", "url": "https://finance.eastmoney.com/a/202609193879237148.html"}]}, {"title": "国内／海外｜供应链核验：Optimus 审厂传闻尚未获一致确认", "date": "9 月 18 日 13:03 报道，约 72 小时内。", "body": "第一财经向相关公司核实审厂消息时，拓普接电人员称未接到相关审厂通知，同时介绍了执行器方面的合作；均胜以保密要求未作回应，三花人员称不清楚新一轮审厂情况。特斯拉截至该报道发稿时未回应。当前能够确认的是各方回应，不能据此确认新增订单、批量供货或量产时间表。", "analysis": "把正式订单、定点披露和可核验出货作为后续跟踪依据，避免将汽车客户关系直接等同于机器人供货关系。", "sources": [{"label": "第一财经原文", "url": "https://m.yicai.com/news/103369671.html"}]}, {"title": "算法专题｜GPT-6 Astra与机器人：混合策略与上下文学习", "date": "近期研究补充，非今日新发布；GPT-Policy预印本于9月16日提交。", "body": "《GPT 6 Astra as an Embodied Policy》作者主页披露：所选RoboDojo任务中，π0.5＋Astra混合策略成功率48%，直接控制26%，仅代表该组实验。另一项GPT-Policy研究连接上下文编译、VLM提出动作与受约束控制器；真机中人类示范视频有帮助，接触任务增加对齐动作参考进一步改善，但精确接触、结果核验和安全仍存在缺口。两项研究不能混为同一评测，也不能据此推论全面替代VLA。", "analysis": "建议在相同任务和预算下比较专用VLA、Astra工具调用与混合纠偏，同时记录耗时、费用、人工介入及失败恢复，以整体任务收益判断采用价值。", "sources": [{"label": "作者说明", "url": "https://shuyumo2003.github.io/"}, {"label": "策略代码", "url": "https://github.com/anonymous-report-421/GPT-as-Policy"}, {"label": "GPT-Policy论文", "url": "https://arxiv.org/abs/2609.19138"}]}, {"title": "算法／新论文：Coda 用末端纠正改善 VLA 推理效率", "date": "9 月 18 日提交，arXiv 预印本；较截止时间略超 72 小时。", "body": "《Fewer Steps, Better Actions》冻结原有策略，只训练轻量纠正器。在 50 个 RoboTwin Easy 仿真任务中，五步 Coda 成功率为 74.68%，对应五步基线为 71.64%；相对默认十步策略，模型前向延迟降低 30.2%。论文明确实验在仿真中进行，延迟不包含通信和机械执行，视觉随机化下也没有清晰的平均提升。", "analysis": "适合评估能否在不重训整套 VLA 的情况下缩短推理时间，但需要重新验证真机闭环表现。", "sources": [{"label": "论文及全文入口", "url": "https://arxiv.org/abs/2609.21216"}]}, {"title": "海外｜模型发布补充：Figure Helix 2.5 测试陌生住宅泛化", "date": "9 月 17 日官方发布，上周重要进展。", "body": "Figure 报告在 30 个未采集训练数据的住宅测试整理客厅、叠毛巾和铺床。其受控对比中，使用 Index 人类行为数据预训练后，完整任务成功率从 9% 提升到 56%。这些结果是公司披露，覆盖指定三类行为，尚不能推论机器人已能处理任意家务或达到消费级可靠性。", "analysis": "关注人类行为数据能否减少逐场景采集成本，并要求披露失败类型、人工干预与任务覆盖边界。", "sources": [{"label": "Figure 官方技术说明", "url": "https://www.figure.ai/news/helix-2-5-zero-shot-30-home-generalization"}]}, {"title": "海外｜论文补充：RoM-Nav 在宇树 G1 上验证跨楼层导航", "date": "9 月 16 日提交；预印本，项目页标注 ICRA 2027 在审。", "body": "加州理工等研究者先在简化动力学中学习导航，再迁移到完整人形系统，结合激光雷达和深度输入，并在策略输出端加入 Poisson 安全过滤器。项目展示 G1 在真实建筑中无地图跨楼层行走；两类分布外障碍各 10 次对比实验中，加入过滤器后均未观察到碰撞，但到达目标耗时增加。", "analysis": "导航训练与运动控制分层值得借鉴；小样本无碰撞不等于普遍安全保证，仍需测试感知盲区和人员混行。", "sources": [{"label": "论文", "url": "https://arxiv.org/abs/2609.19272"}, {"label": "作者项目与视频", "url": "https://wdc3iii.github.io/rom-nav/"}]}], "followups": ["启元 10 月 1 日起的实际交付、版本可用性及用户反馈。", "触觉传感器真实交付、寿命，以及对操作成功率的增益。", "Optimus 正式订单与量产披露，VLA 加速和住宅泛化能否在更多真机复现。"]}];